INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1135, 'koKR', 'Jad z Wysokiej Grzędy', 'Jak pewnie wiesz, orkowie często oswajają wiwerny i jeżdżą na nich. Mniej znany jest fakt, że w pewnych kręgach jad wiwerny ceni się wyżej niż samą bestię. Jeśli więc nie boisz się trochę zapolować na wiwerny, to... mam dla ciebie zadanie.$B$BNa zachód stąd, w krainie Tysiąca Filarów, leży miejsce zwane Wysoką Grzędą. Tamtejsze wiwerny mają silny jad. Silny i cenny.', 'Przynieś 10 gruczołów jadowych wiwern z Wysokiej Grzędy Fiorze Długie Uszy w Theramore.', '', 'Wróć do Fiory Długie Uszy na Skraju Mgły na Mrocznym Wybrzeżu.', '', '', '', '', 0),
(1166, 'koKR', 'Zmartwienie nadrządcy Mok\'Morokka', 'Pokłonić się nadrządcy Mok\'Morokkowi!$b$bRexxar zrobić ze mnie potężnego wodza klanu Kamiennych Maczug!$b$bJa dobry wódz. Ja pilnować, żeby klan bezpieczny.$b$bDuże smoki przyjść i zrobić ogień w starym domu. Ja mądry ogr. Znaleźć tu nowy dom dla klanu.$b$bUciekać ze starego domu tak szybko, że ja zapomnieć rzeczy. Maluchu, iść po moje rzeczy. Iść na południe i znaleźć mój pyszny grog, moją tabakę i moją kasetkę. Ja cię lubić, jak ty to zrobić. Ty szukać w Norze Płomienia i Ruinach Kamiennych Maczug... one tam być, ja pewny!', 'Odzyskaj grog, tabakę i kasetkę nadrządcy Mok\'Morokka z Paprotni, pozostawione na Pyłowym Bagnisku.', '', 'Wróć do nadrządcy Mok\'Morokka w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1168, 'koKR', 'Armia czarnego smoka', 'Rexxar zrobić Mok\'Morokka nadrządcą. On bardziej dbać o władzę niż o ogry.$b$bCzarne smoki zabić dużo ogrów. Zabić żonę Tharga. Mok\'Morokk kazać nam uciekać. Kazać przyjść tutaj.$b$bOgr powinien walczyć. Ogry nie umieć dobrze uciekać. Mok\'Morokk dbać tylko o Mok\'Morokka.$b$bDla mnie dom to Ruiny Kamiennych Maczug. Ja lubić południe. To miejsce to nie dom.$b$bPomóc ogrom walczyć z armią czarnego smoka. Ja chcieć zemsty. Ja chcieć wrócić do domu.', 'Zabij dla Tharga z Paprotni 10 zwiadowców Ognistej Grzywy, 10 popielnych ogonów Ognistej Grzywy i 5 zgubołusków Ognistej Grzywy.', '', 'Wróć do Tharga w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1169, 'koKR', 'Rozpoznanie miotu', 'Podczas gdy ten tchórzliwy głupiec Mok\'Morokk pławi się we władzy, a Tharg zmaga się z demonami żalu i zemsty i zabiega o przywództwo w klanie, ja jeden, jak się zdaje, troszczę się o ustalenie, kto stoi za napaścią na nasz dawny dom.$b$bSkąd to zdumione spojrzenie, $n? Czyżbyś $gspodziewał:spodziewała; się, że będę się wysławiał jak nieokrzesany gbur tylko dlatego, że jestem ogrem?$b$bWróćmy jednak do rzeczy: przynieś mi serca i języki smoczych piskląt, zarówno podrośniętych, jak i świeżo wyklutych. Dotrę do korzeni tego zła...', 'Przynieś Draz\'Zilbowi w Paprotni 7 palących języków i 7 palących serc.', '', 'Wróć do Draz\'Zilba w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1170, 'koKR', 'Miot Onyxii', 'Na Wioskę Kamiennych Maczug napadł miot Onyxii. Ale dlaczego córka Śmiercioskrzydłego, władcy czarnych smoków, miałaby spaść na nasze ziemie?$b$bTo wielce niepokojące. Z pewnością Onyxię przywiódł tu cel poważniejszy niż oblężenie garstki ogrów.$b$bNatychmiast powiadom Mok\'Morokka! Trzeba działać.', 'Porozmawiaj z nadrządcą Mok\'Morokkiem w Paprotni.', '', '', '', '', '', '', 0),
(1171, 'koKR', 'Miot Onyxii', 'Ty teraz dać mi spokój. Iść powiedzieć Draz\'Zilbowi, że my tu zostać. Tu nie być czarnego smoka.', 'Porozmawiaj z Draz\'Zilbem w Paprotni.', '', '', '', '', '', '', 0),
(1172, 'koKR', 'Miot Onyxii', 'Miot Onyxii rozproszył się po Smoczym Mroku. Nie wolno dopuścić, by wykluły się kolejne pisklęta.$b$bŚpiesz na Żmijowe Trzęsawisko na południu Pyłowego Bagniska. Z pewnością tam urządziła sobie leże. Wytrop jaja złej smoczycy i je zniszcz.$b$bNigdy nie odzyskamy Wioski Kamiennych Maczug, jeśli okolica pozostanie wylęgarnią.$b$bCo do Mok\'Morokka... wobec tego nicponia mam inne plany.', 'Zniszcz 5 jaj Onyxii dla Draz\'Zilba z Paprotni.', '', 'Wróć do Draz\'Zilba w Paprotni na Pyłowym Bagnisku.', 'Zniszczone jaja Onyxii', '', '', '', 0),
(1173, 'koKR', 'Wyzwij nadrządcę Mok\'Morokka', 'Ty śmieć wyzywać nadrządcę Mok\'Morokka?$b$bHa!$b$bJa zgnieść malucha!$b$bTy powiedzieć, jak chcieć dostać porządne lanie.', 'Pokonaj Mok\'Morokka i zanieś wieści Draz\'Zilbowi w Paprotni.', 'Przepędź nadrządcę Mok\'Morokka z Paprotni', 'Wróć do Draz\'Zilba w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1177, 'koKR', 'Głodny!', 'Błotogniot duży ogr.$b$bJa głodny.$b$bIść walnąć rybka. Przynieść Błotogniotowi jedzenie.$b$bTy nakarmić Błotogniota albo Błotogniot zjeść ciebie.', 'Przynieś 8 głów błotopłetwych Błotogniotowi Brudnostopemu na północy Pyłowego Bagniska.', '', 'Wróć do Błotogniota Brudnostopego na Pyłowym Bagnisku.', '', '', '', '', 0),
(1201, 'koKR', 'Szpiedzy z Theramore', 'Hordę i Przymierze łączy kruchy rozejm. Na rubieżach obie strony toczą potyczki i prowadzą tajne działania przeciwko sobie, a naszym obowiązkiem jest dopilnować, by to Horda była górą!$B$BTeraz nadarza się po temu okazja.$B$BInfiltratorzy Przymierza zajęli pozycje na wschód od Paprotni. Szpiegują wioskę i donoszą o naszych ruchach do Theramore, a na to nie możemy pozwolić.$B$BWytrop infiltratorów i ich zabij. Niech ich przełożeni dostaną jasny sygnał, że nie będziemy tolerować obecności ich szpiegów!', 'Zabij 9 infiltratorów z Theramore, a następnie wróć do Nazeera Krwawej Piki w Paprotni.', '', 'Wróć do Nazeera Krwawej Piki w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1202, 'koKR', 'Doki Theramore', '$N, dwóch naszych szpiegów wysłano, by wykradli dokumenty ze statku w dokach Theramore. Zdobyli papiery, ale zostali wykryci i musieli wyrzucić dokumenty do morza.$B$BJeden ze szpiegów później uciekł, lecz nie zdołał odzyskać zdobyczy. Zameldował mi o porażce, a ja powierzam teraz to zadanie tobie.$B$BDokumenty są w kufrze, gdzieś w wodzie pod dokami Theramore. Znajdź je, $N, i przynieś mi.', 'Przynieś dokumenty kapitana Nazeerowi Krwawej Pice w Paprotni.', '', 'Wróć do Nazeera Krwawej Piki w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1203, 'koKR', 'Jarl potrzebuje ostrza', 'Mam coś do przycięcia. Nie mogę ci powiedzieć, co zamierzam ciąć, ale... potrzebne mi ostrze. Pewne ostrze...$B$BNiektórzy nazywają to mieczem. Ja nazywam to kosą.$B$BPomożesz mi? Te rybie ludki, no wiesz, murloki czy jak im tam... Jest taki jeden, nazywają go Brzytwogrzbietem, nosi wielki miecz, mieszka na północ stąd, niedaleko plaży. To tego miecza potrzebuję!$B$BAle nie ociągaj się. To, co mam do przycięcia, nie będzie czekać wiecznie...', 'Przynieś miecz Brzytwogrzbieta „Bagiennemu Oku” Jarlowi we Dworze Bagiennego Światła.', '', 'Wróć do „Bagiennego Oka” Jarla we Dworze Bagiennego Światła na Pyłowym Bagnisku.', '', '', '', '', 0),
(1204, 'koKR', 'Zupa błotnoskalna z robalami', 'Pracuję nad daniem, które nazywam „Zupa błotnoskalna z robalami”. Wciąż brakuje mi głównych składników i... cóż, chyba długo bym nie pociągnął, brnąc przez Pyłowe Bagnisko!$B$BWięc, $N, zapolujesz dla mnie? Najpierw potrzebuję języków błotnoskalnych żółwi. Znajdziesz je wzdłuż wybrzeża, głównie wokół zatoki.$B$BAle nie chcę byle jakich języków! Słyszałem, że niektóre błotnoskalne żółwie mają rozwidlone języki...$B$BPodobno rozwidlone języki mają wyjątkowy smak, a ja chcę, żeby moje danie miało właśnie ten smak...', 'Przynieś 8 rozwidlonych języków błotnoskalnych żółwi Morganowi Sternowi w Theramore.', '', 'Wróć do Morgana Sterna na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(1206, 'koKR', 'Jarl potrzebuje oczu', 'Sok z oczu to dobry sok do picia. Szkoda, że większość stworzeń ma tylko dwoje oczu.$B$BAle pająki mają mnóstwo oczu. Mnóstwo i mnóstwo. A sok z oczu ciemnomglistych pająków jest smaczny. Gładki i słony! Niepęknięte pajęcze oczy... już czuję ich smak.$B$BCiemnomgliste pająki siedzą na zachód stąd, w Pieczarze Mrocznej Mgły. Myślisz, że to pająki wzięły nazwę od pieczary... czy na odwrót?', 'Przynieś 20 niepękniętych oczu ciemnomglistych pająków „Bagiennemu Oku” Jarlowi we Dworze Bagiennego Światła.', '', 'Wróć do „Bagiennego Oka” Jarla we Dworze Bagiennego Światła na Pyłowym Bagnisku.', '', '', '', '', 0),
(1218, 'koKR', 'Udka żab bagiennych', 'Lubię gotować. Dobra bagienna kuchnia. Smażone zielone żabie udka i takie tam.$B$BA udek mi zabrakło. Za to dwór roi się od żab. Olbrzymich żab bagiennych. $GPrzyniósłbyś:Przyniosłabyś; mi trochę tych udek? Nic trudnego, naprawdę. Tylko pac w łeb i przynosisz mi udka.$B$BPotem zrobię gulasz, zagotuję, wciągnę i tobie też dam.$B$BLubisz gulasz?', 'Przynieś 10 udek żab bagiennych „Bagiennemu Oku” Jarlowi na Pyłowym Bagnisku.', '', 'Wróć do „Bagiennego Oka” Jarla na Wzgórzu Czarownic na Pyłowym Bagnisku.', '', '', '', '', 0),
(1219, 'koKR', 'Raport orka', 'W sypkiej ziemi znajdujesz odciętą dłoń orka. Dłoń ściska tubę wyrzeźbioną z kości. A w tubie tkwi poplamiony ziemią pergamin.$B$BPergamin jest zapisany po orkowemu... i wygląda na ważny.', 'Zanieś raport szpiega porucznikowi Adenowi w Theramore.', '', '', '', '', '', '', 0),
(1220, 'koKR', 'Kapitan Vimes', 'Kapitan Vimes powinien zobaczyć raport orka, który $gznalazłeś:znalazłaś;, $N. Zna orkowy język lepiej niż większość z nas. I powinien się dowiedzieć, że w pobliżu Theramore kręcą się szpiedzy Hordy!$B$BKapitan jest w koszarach, w północno-wschodniej części Wyspy Theramore.', 'Zanieś raport szpiega kapitanowi Garranowi Vimesowi.', '', '', '', '', '', '', 0),
(1222, 'koKR', 'Ucieczka Śmierdziela', 'Świetnie, nareszcie coś, co nie chce mnie zjeść!$B$BPotrzebuję pomocy z tutejszymi bestiami, a ty pasujesz jak ulał, $gkolego:paniusiu;.$B$BKucharz Morgan Stern pracuje nad nowym przepisem i wysłał mnie tu po liście bobrka. Chyba uważa, że są smaczne.$B$BW każdym razie, kiedy szukałem bobrka... otoczyli mnie! Pomożesz mi się stąd wydostać i popilnujesz moich pleców, kiedy będę szukał bobrka?', 'Odeskortuj „Śmierdziela” Ignatza, a potem porozmawiaj z Morganem Sternem w Theramore.', 'Pomóż Śmierdzielowi znaleźć liście bobrka', 'Wróć do Morgana Sterna na Wybrzeżu Męciwód na Pyłowym Bagnisku.', '', '', '', '', 0),
(1238, 'koKR', 'Zaginiony raport', 'W przesiewanej luźnej ziemi ukazuje się odcięta dłoń orka. Dłoń zaciska się na tubie wyrzeźbionej z kości. A w tubie tkwi poplamiony ziemią pergamin.$B$BPergamin to raport orka, który tygodniami szpiegował miasto Theramore.$B$BPo przejrzeniu pergaminu staje się jasne, że trzeba go zanieść orkowemu mistrzowi szpiegów w Paprotni.', 'Zanieś raport szpiega Nazeerowi Krwawej Pice w Paprotni.', '', '', '', '', '', '', 0),
(1239, 'koKR', 'Odcięta głowa', 'Energiczne kopanie odsłania głowę orka, nierówno odciętą przy szyi. Wargi zastygły w grymasie, a ciemne oczy patrzą hardo.', 'Zanieś głowę hardego orka Nazeerowi Krwawej Pice w Paprotni.', '', '', '', '', '', '', 0),
(1251, 'koKR', 'Czarna tarcza', 'Żelazna tarcza, poczerniała od ognia, który strawił karczmę, wisi przytwierdzona do rozsypującego się komina – jednej z niewielu ocalałych części budowli, która niegdyś była karczmą „Cienisty Wypoczynek”.$b$bTarczę da się zdjąć z cegieł komina.', 'Zanieś tarczę z czernionego żelaza Krogowi w Paprotni.', '', '', '', '', '', '', 0),
(1252, 'koKR', 'Porucznik Paval Reethe', 'Twój wzrok przyciąga błysk światła spod gruzów. Gdy zgarniasz szczątki i popiół oblepiające przedmiot, ukazuje się insygnium: złota kotwica na białej emalii – znak Theramore.$b$bPod kotwicą wytłoczono nazwisko „Porucznik Paval Reethe”.', 'Zanieś odznakę Reethe\'a kapitanowi Garranowi Vimesowi w Theramore.', '', '', '', '', '', '', 0),
(1253, 'koKR', 'Czarna tarcza', 'Żelazna tarcza, poczerniała od ognia, który strawił karczmę, wisi przytwierdzona do rozsypującego się komina – jednej z niewielu ocalałych części budowli, która niegdyś była karczmą „Cienisty Wypoczynek”.$b$bTarczę da się zdjąć z cegieł komina.', 'Zanieś tarczę z czernionego żelaza kapitanowi Garranowi Vimesowi w Theramore.', '', '', '', '', '', '', 0),
(1258, 'koKR', '... z robalami', 'Kolejnym składnikiem mojego nowego przepisu jest odnóże olbrzymiego kraba w skorupie. A kraby z Pyłowego Bagniska – mułoskorupe, jak je tu nazywają – zupełnie się nie nadają! Obawiam się, że jedyne odpowiednie kraby żyją daleko stąd, na Moczarach Smutków.$B$BSkorupa odnóża to kluczowy element prezentacji dania, więc potrzebuję nieskazitelnych, nieporysowanych odnóży. Dorosły krab ma najwyżej jedno albo dwa takie odnóża, a ja potrzebuję wielu, żeby dopracować danie.$B$BWięc, $N... wybierzesz się w podróż?', 'Przynieś 12 nieskazitelnych odnóży pełzaczy Morganowi Sternowi w Theramore.', '', 'Wróć do Morgana Sterna na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(1259, 'koKR', 'Porucznik Paval Reethe', 'Nie kojarzę nazwiska porucznika Pavala Reethe\'a. Najlepiej zapytaj adiutanta Tesorana. Prowadzi całą dokumentację straży Theramore, od personelu po wyposażenie.$b$bPo szybkim przejrzeniu ksiąg powinien ci powiedzieć, kim jest ten Reethe.', 'Dowiedz się więcej o Reethe\'u od adiutanta Tesorana w Theramore.', '', '', '', '', '', '', 0),
(1263, 'koKR', 'Płonąca karczma <CHANGE TO GOSSIP>', '', '', '', '', '', '', '', '', 0),
(1268, 'koKR', 'Podejrzane ślady kopyt', 'Od wciąż dymiącego szkieletu karczmy „Cienisty Wypoczynek” odchodzą rzędy śladów kopyt. Widać co najmniej kilka wyraźnych odcisków, a kolejne rzędy śladów są niemal niedostrzegalne w miękkim bagiennym błocie.', 'Zgłoś Krogowi w Paprotni podejrzane ślady przy karczmie „Cienisty Wypoczynek”.', '', '', '', '', '', '', 0),
(1269, 'koKR', 'Porucznik Paval Reethe', 'Twój wzrok przyciąga błysk światła spod gruzów. Gdy zgarniasz szczątki i popiół oblepiające przedmiot, ukazuje się insygnium: złota kotwica na białej emalii – znak Theramore.$b$bPod kotwicą wytłoczono nazwisko „Porucznik Paval Reethe”.', 'Zanieś odznakę Reethe\'a Krogowi w Paprotni.', '', '', '', '', '', '', 0),
(1272, 'koKR', 'Poszukiwanie Reethe\'a <CHANGE INTO GOSSIP>', '', '', '', '', '', '', '', '', 0),
(1273, 'koKR', 'Przesłuchanie Reethe\'a', 'Długo to trwało, ale znalazłem Reethe\'a. Dobrze się chować jak na człowieka.$b$bOgron się martwić, że on mógł zwariować po tak długim czasie na bagnie. Ty iść ze mną, my wyciągnąć z niego odpowiedzi.', 'Idź z Ogronem porozmawiać z Reethe\'em, a następnie wróć do Kroga w Paprotni.', 'Przesłuchaj Reethe\'a z Ogronem', 'Wróć do Kroga na Pyłowym Bagnisku.', '', '', '', '', 0),
(1279, 'koKR', '<nyi> <TXT>Ślady kopyt centaurów', '', '', '', '', '', '', '', '', 0),
(1280, 'koKR', '<nyi> <TXT>Ślady kopyt centaurów', '', '', '', '', '', '', '', '', 0),
(1281, 'koKR', 'Piosenka Jima <CHANGE TO GOSSIP>', '', '', '', '', '', '', '', '', 0),
(1282, 'koKR', 'Nazywają go Uśmiechniętym Jimem', 'Nic nie poradzę, że żal mi starego Jima. Nie zawsze taki był. Prowadził kiedyś karczmę na bagnach, wspaniałe miejsce.$b$bSłuchaj, naprawdę nie chcę o tym mówić. Jeśli musisz, porozmawiaj o tym z kapitanem Vimesem. Stacjonuje na najwyższym piętrze Cytadeli Przyczółku, dużych koszar na wschód od wieży lady Jainy.', 'Porozmawiaj z kapitanem Garranem Vimesem na najwyższym piętrze Cytadeli Przyczółku.', '', '', '', '', '', '', 0),
(1283, 'koKR', 'Pożar w „Cienistym Wypoczynku” <CHANGE TO GOSSIP>', '', '', '', '', '', '', '', '', 0),
(1284, 'koKR', 'Podejrzane ślady kopyt', 'Od wciąż dymiącego szkieletu karczmy „Cienisty Wypoczynek” odchodzą rzędy śladów kopyt. Widać co najmniej kilka wyraźnych odcisków, a kolejne rzędy śladów są niemal niedostrzegalne w miękkim bagiennym błocie.', 'Zamelduj kapitanowi Garranowi Vimesowi w Theramore o podejrzanych śladach przy karczmie „Cienisty Wypoczynek”.', '', '', '', '', '', '', 0),
(1285, 'koKR', 'Ludzie Daelina', 'Reddon... Redpath... Ach, jest! Porucznik Paval Reethe.$b$bWstąpił do straży Theramore razem z większością rekrutów, którzy przypłynęli przez morze z lady Proudmoore. W wieku szesnastu lat zaciągnął się do piechoty morskiej Kul Tiras. Wzorowa służba, awanse...$b$bFiguruje jako zaginiony.', 'Przekaż kapitanowi Garranowi Vimesowi w Theramore informacje o Reethe\'u.', '', '', '', '', '', '', 0),
(1286, 'koKR', 'Dezerterzy', 'Utrzymanie się na bagnach to ciężka walka, ale dzięki sile naszej determinacji zdołaliśmy utrzymać w okolicy kilka obronnych wież strażniczych.$b$bZ najnowszych informacji i raportów zwiadowców wynika, że grupa dezerterów zajęła naszą opuszczoną wieżę na Straconym Cyplu, na południowy wschód od karczmy.$b$bIch miejscowym dowódcą jest chyba Balos Jacken. Spróbuj coś z niego wyciągnąć.$b$bOstrzegam cię, $n. To może być twardy orzech do zgryzienia.', 'Zdobądź od Balosa Jackena i dezerterów na Pyłowym Bagnisku informacje o Reethe\'u.', '', '', '', '', '', '', 0),
(1287, 'koKR', 'Dezerterzy', 'Reethe? Ten tchórz?$b$bWyrzuciliśmy go z obozu, bo upierał się, żeby napadać na zapasy ogrów w Paprotni. Nie jest nas tylu, żebyśmy mogli stawić czoła tym bezmózgim bydlakom.$b$bZa często przeginał, więc zostawiliśmy go samemu sobie.$b$bNo, pomogłem ci... To może ty pomożesz nam i zapomnisz, że nas $gspotkałeś:spotkałaś;?', 'Porozmawiaj z kapitanem Garranem Vimesem w Theramore o Reethe\'u.', '', '', '', '', '', '', 0),
(1288, 'koKR', 'Raport Vimesa', 'Dobra robota, $n, najlepsza, jaką widziałem u amatora.$b$bLady Proudmoore prosiła, żebym informował ją na bieżąco o tej delikatnej sprawie, a od dłuższego czasu z nią nie rozmawiałem.$b$bMiałem zanieść jej raport później, ale bardziej stosowne wydaje się, żebyś to ty z nią o tym $gporozmawiał:porozmawiała;. Pewnie lepiej ode mnie odpowiesz na jej pytania.', 'Zanieś raport Vimesa lady Jainie Proudmoore w Theramore.', '', '', '', '', '', '', 0),
(1289, 'koKR', '<nyi> Raport Vimesa', 'Cóż, sądząc z raportu kapitana Vimesa, $gbyłeś:byłaś; ogromną pomocą w jego śledztwie i za to ci dziękuję.$b$bSpokojniej mi, gdy wiem, że sprawa jest w tak dobrych rękach. Jeśli możesz, proszę, wróć do kapitana Vimesa i pomóż mu dotrzeć do sedna tej zagadki.', 'Wróć do kapitana Garrana Vimesa w Theramore.', '', '', '', '', '', '', 0),
(1291, 'koKR', '<nyi> <TXT> Ślady kopyt centaurów', '', '', '', '', '', '', '', '', 0),
(1292, 'koKR', '<nyi><TXT> Ślady kopyt centaurów', '', '', '', '', '', '', '', '', 0),
(1293, 'koKR', '<nyi> <TXT> Ślady kopyt centaurów', '', '', '', '', '', '', '', '', 0),
(1294, 'koKR', '<nyi> <TXT>Sympatia do centaurów', '', '', '', '', '', '', '', '', 0),
(1295, 'koKR', '<nyi> <TXT> Plan działania', '', '', '', '', '', '', '', '', 0),
(1296, 'koKR', '<nyi> <TXT> Plan działania', '', '', '', '', '', '', '', '', 0),
(1297, 'koKR', '<nyi> <TXT> Plan działania', '', '', '', '', '', '', '', '', 0),
(1319, 'koKR', 'Czarna tarcza', 'Przykro mi, że niewiele mogę pomóc, $n, ale mogę cię skierować do kogoś, kto może. Caz Dwutryb, jeden z naszych najlepszych kowali, pracuje przy palenisku w kuźni.$b$bZanieś mu tarczę i zobacz, co ci powie.', 'Pokaż tarczę z czernionego żelaza Cazowi Dwutrybowi w Theramore.', '', '', '', '', '', '', 0),
(1320, 'koKR', 'Czarna tarcza', 'Ach, prawie bym to przeoczył... Skórzany pasek z tyłu musiał się spalić, ale wygląda na to, że tarczę zrobiono dla kogoś dużego. Obstawiałbym, że dla taurena.$b$bTo w zasadzie wszystko, co mogę ci powiedzieć. Przekaż kapitanowi Vimesowi, że przykro mi, że nie mogłem bardziej pomóc.', 'Porozmawiaj z kapitanem Garranem Vimesem w Theramore.', '', '', '', '', '', '', 0),
(1321, 'koKR', 'Czarna tarcza', 'Hmm... Nie widzę w tej tarczy nic niezwykłego. Niech obejrzy ją Do\'gol, kowal – może powie nam o niej coś więcej, ale nie robiłbym sobie nadziei...', 'Pokaż tarczę z czernionego żelaza Do\'golowi w Paprotni.', '', '', '', '', '', '', 0),
(1322, 'koKR', 'Czarna tarcza', 'Hmmm, tu na brzegu tarczy jest napis, ale trudno go odczytać przez to całe spalone paskudztwo.$b$bPotrzebuję kwasu, żeby go oczyścić. Dobry byłby jad ciemnomglistych pająków. Pająki zajęły starą kopalnię, Pieczarę Mrocznej Mgły, na północny zachód od wioski. Przynieś mi trochę ich gruczołów, a to wyczyszczę.', 'Zdobądź 5 kwasowych gruczołów jadowych dla Do\'gola w Paprotni.', '', 'Wróć do Do\'gola w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(1323, 'koKR', 'Czarna tarcza', 'Och, chyba wylałem na tarczę za dużo kwasu. Tylko trochę przetrę...$b$bHm, trudno odczytać, ale wygląda to na imię Mosarn. Nigdy o nim nie słyszałem. Może Krog wie. Krog zna dużo ludzi.', 'Porozmawiaj z Krogiem w Paprotni.', '', '', '', '', '', '', 0),
(1390, 'koKR', '<nyi> Ups, znowu ich zabiliśmy.', '', '', '', '', '', '', '', '', 0),
(1948, 'koKR', 'Przedmioty mocy', 'Wykonanie różdżki maga nie jest łatwe. Potrzebne są rzadkie substancje, a także naczynie zdolne pomieścić ogromne ilości magicznej energii. Musisz zebrać te rzeczy i mi je przynieść.$B$BNa tym pergaminie zapisałam, czego potrzebujesz i jak to zdobyć. Przynieś mi dokładnie to, co jest na liście, i trzymaj się moich pisemnych wskazówek co do joty, bo jeśli tego nie zrobisz, to przy wykonywaniu twojej różdżki sprawy mogą pójść... źle.', 'Przynieś 1 nefryt i jeżynę naładowaną piorunem do Tabethy na Pyłowym Bagnisku.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(1952, 'koKR', 'Różdżka maga', 'Idę teraz zrobić różdżki.', 'Porozmawiaj z Tabethą po jej rytuale.', '', '', '', '', '', '', 0),
(1954, 'koKR', 'Piekielna kula', 'Pierwszy krok to zdobycie kuli, w której drzemie moc. Czarnoksiężnicy z Płonącego Ostrza mają ładne, wysokiej jakości kule... szkoda tylko, że uwięzili w nich demony! Ale damy radę to naprawić, o tak.$B$BUdaj się do Mrocznego Pustkowia i wyrwij piekielną kulę przywoływaczowi z Płonącego Ostrza. Przywoływaczy znajdziesz w Sabacie Mannoroca.$B$BKiedy zdobędziesz kulę, wróć do mnie.', 'Przynieś piekielną kulę do Tabethy na Pyłowym Bagnisku.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(1955, 'koKR', 'Egzorcyzm', 'Skoro mamy już kulę przywoływacza, musimy wypędzić z niej demona. To mogę zrobić ja. To ta łatwa część.$B$BTo ty masz trudne zadanie. To ty musisz zabić demona, kiedy już wyjdzie.$B$BI musisz się sprężać. Jeśli będziesz zwlekać za długo, wskoczy z powrotem do kuli i będziemy musieli zaczynać od nowa!$B$BWięc się przygotuj. Naszykuj najsilniejsze zaklęcia, miej mikstury pod ręką i weź ze sobą przyjaciela, jeśli jakiegoś masz. Bo nie będzie to przyjemny widok.', 'Zabij demona z kuli, a potem porozmawiaj z Tabethą.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(1956, 'koKR', 'Moc w Uldamanie', 'Skoro demon został usunięty, musimy zdobyć źródło zasilania. Niestety, najlepsze źródła zasilania są zwykle najstarsze i najtrudniejsze do zdobycia. Zabawne, jak los czasem lubi kąsać, prawda?$B$BMusisz więc udać się do Uldamanu i pokonać tamtejszego obsydianowego strażnika. Jest wielki, twardy, a jego źródło zasilania ma niezłego kopa!$B$BŻyczę ci powodzenia, $N. A jeśli szczęście ci nie dopisze, no cóż... miło było cię poznać.', 'Zdobądź obsydianowe źródło zasilania i zanieś je do Tabethy na Pyłowym Bagnisku.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(1957, 'koKR', 'Przypływy many', 'Jesteśmy prawie u celu, ale ten ostatni krok jest najniebezpieczniejszy, $N.$B$BMam pustą kulę przywoływacza i jestem gotowa napełnić ją mocą. Zrobimy to, wykorzystując energię szczeliny many. Rzucę zaklęcie, które na chwilę otworzy szczelinę, a z niej wyleją się stworzenia – przypływy many. Musisz pokonać przypływy many, a wtedy ich moc zostanie uwolniona, a ja ją zbiorę.$B$BZabij dość przypływów many, zanim szczelina się zamknie, a całą zebraną energię umieszczę w twojej kuli.', 'Zabij 12 przypływów many w wyznaczonym czasie.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(1958, 'koKR', 'Niebiańska moc', '', '', '', '', '', '', '', '', 0),
(2846, 'koKR', 'Tiara głębin', 'Dawno temu miałam piękny klejnot, Tiarę głębin. I była nie tylko piękna – kryła wielką moc dla tych, którzy wiedzieli, jak jej użyć.$B$BGdy więc wieść o tiarze dotarła do hydromantki Velrathy, ta musiała ją mieć. Wysłała swoich agentów do mojego domu i ukradli ją pod moją nieobecność. Złodzieje!$B$BChcę odzyskać moją tiarę! Udaj się do Zul\'Farrak, miasta trolli w Tanaris, odnajdź Velrathę i wyrwij jej tiarę. Zwróć mi ją, a zyskasz moją przychylność.', 'Przynieś Tiarę głębin do Tabethy na Pyłowym Bagnisku.', '', 'Wróć do Tabethy na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(4961, 'koKR', 'Oczyszczenie kuli Orahila', 'Ach, kula przywoływacza – to z niej musi pochodzić skaza. Musimy wypędzić z niej demona, jeśli masz jej używać. To mogę zrobić bez trudu.$B$BTo ty masz trudne zadanie. Musisz zabić demona, gdy go uwolnię.$B$BI musisz się sprężać. Jeśli będziesz zwlekać za długo, wróci do kuli i będziemy musieli zaczynać od nowa!$B$BWięc się przygotuj, $N. Naszykuj najsilniejsze zaklęcia, miej mikstury pod ręką i weź ze sobą przyjaciela, jeśli jakiegoś masz. Bo nie będzie to przyjemny widok.', 'Zabij demona z kuli, a potem porozmawiaj z Tabethą.', '', 'Wróć do Tabethy na Farmie Tabethy na Pyłowym Bagnisku.', '', '', '', '', 0),
(6570, 'koKR', 'Emberstrife', 'Nasyciłam ten medalion magią potrzebną, by stworzyć i podtrzymać iluzję w obrębie nory Emberstrife\'a.$B$BEmberstrife to prastary smok; dawny odźwierny Nefariana, obarczony obowiązkiem poddawania próbom tych smoczych pomiotów, które chcą wznieść się do rangi elitarnej straży Onyxii.$B$BUdaj się na Żmijowe Trzęsawisko na Pyłowym Bagnisku i wejdź do leża Emberstrife\'a. Gdy tam dotrzesz, załóż amulet i podążaj tam, dokąd zaprowadzi cię przeznaczenie!$B', 'Udaj się na Żmijowe Trzęsawisko na Pyłowym Bagnisku i odszukaj Norę Emberstrife\'a. W środku załóż Amulet smoczej wywrotowości i porozmawiaj z Emberstrife\'em.$B', '', '', '', '', '', '', 0),
(6582, 'koKR', 'Próba czaszek: Scryer', 'Jesteśmy dziećmi Śmiercioskrzydłego, pisklę. Musimy narzucić naszą dominację pomniejszym Aspektom.$B$BJeśli naprawdę jesteś $ggodny:godna; wyniesienia, pomniejsze stado zwiędnie w twojej obecności.$B$BZnajdź ich czempionów i zetrzyj ich w proch w imię naszego Ojca!$B$BUdaj się do Zimozdroju i wytrop potężnego błękitnego smoka, Scryera. Zmiażdż go i każdego z Błękitnego Stada, kto stanie ci na drodze. Wyrwij mu czaszkę i przynieś ją mnie.', 'Musisz odnaleźć czempiona Błękitnego Stada, smoka Scryera, i go zabić. Wyrwij czaszkę z jego zwłok i zanieś ją Emberstrife\'owi.$B$BWiesz, że Scryera można znaleźć w Zimozdroju.', '', 'Wróć do Emberstrife\'a na Pyłowym Bagnisku.', '', '', '', '', 0),
(6583, 'koKR', 'Próba czaszek: Somnus', 'Tak jak nasz Ojciec miażdży samych Aspektów, tak i my musimy nieść chaos i zniszczenie ich dzieciom.$B$BMusisz sprawdzić swoją sprawność bojową w starciu z bezsennymi śniącymi: dziećmi Zielonego Stada.$B$BUdaj się na Moczary Smutków i wytrop Somnusa, smoczego czempiona Zielonego Stada. Uwolnij swoją nienawiść; zdominuj tego insekta... Wróć do mnie z jego czaszką...', 'Zniszcz Somnusa, smoczego czempiona Zielonego Stada. Zabierz jego czaszkę i zanieś ją Emberstrife\'owi.', '', 'Wróć do Emberstrife\'a w Norze Emberstrife\'a na Pyłowym Bagnisku.', '', '', '', '', 0),
(6584, 'koKR', 'Próba czaszek: Chronalis', 'Strażnicy czasu, dzieci Nozdormu – Władcy Ssstuleci...$B$BTrzech strzeże Jaskiń Czasu, lecz tylko jeden obchodzi Czarne Stado: Przesuwacz Czasu, Chronalis, ulubione smocze młode Nozdormu.$B$BSsspadnij na tego czempiona, zadaj cios, od którego zapłaczą nawet niewzruszone piaski czasu. Wróć do mnie z jego czaszką.', 'Jaskiń Czasu na pustyni Tanaris strzeże Chronalis, dziecię Nozdormu. Zniszcz go i zanieś jego czaszkę Emberstrife\'owi.', '', 'Wróć do Emberstrife\'a w Norze Emberstrife\'a na Pyłowym Bagnisku.', '', '', '', '', 0),
(6585, 'koKR', 'Próba czaszek: Axtroz', 'To nad górami Grim Batol nasz Ojciec toczył bój z połączoną potęgą Aspektów. Tchórzliwy czyn zdrajczyni Alexstrazy dał pozostałym Aspektom dość czasu, by umknęły przed gniewem Ojca.$B$BTaki haniebny czyn... sss...$B$BCzerwone Stado strzeże teraz Grim Batol, a jego porucznik, Axtroz, musi zostać zniszczony. Przynieś mi czaszkę Axtroza. Za Ojca, pisklę!', 'Udaj się do Grim Batol i wytrop Axtroza, smoczego czempiona Czerwonego Stada. Zniszcz go i zabierz jego czaszkę. Zanieś czaszkę Emberstrife\'owi.', '', 'Wróć do Emberstrife\'a w Norze Emberstrife\'a na Pyłowym Bagnisku.', '', '', '', '', 0),
(6607, 'koKR', 'Nat Pagle, wędkarz ekstremalny', 'Nie powiem, żebym jakoś szczególnie lubił łowić. Robię to już chyba dobre 20 albo 30 lat.$B$BSądzę, że każdego pcha do tego, co robi, co innego.$B$BNie mówię, że musisz łowić przez 30 lat albo złowić każdą rybę w morzu, żeby zostać mistrzem wędkarstwa. Sądzę, że wystarczy być upartym – na tyle upartym, żeby godzinami siedzieć na tyłku i nic nie robić.$B$BPowiem ci coś: złów mi kilka rzadkich ryb, a nauczę cię tego i owego. Oto lista:', 'Nat Pagle chce, żebyś $gzłowił:złowiła; następujące ryby:$B$BKoryfenę z Mglistej Trzciny z Wybrzeża Mglistej Trzciny na Moczarach Smutków.$B$BMarlina z Sar\'theris z Wybrzeża Sar\'theris na Mrocznym Pustkowiu.$B$BTuńczyka ahi z Feralas z Rzeki Verdantis w Feralas.$B$BNiebieską żaglicę z Dzikiego Wybrzeża z Dzikiego Wybrzeża w Dolinie Cierniodławów.$B$BWróć do Nata Pagle\'a, kiedy wszystkie wyciągniesz!', '', 'Wróć do Nata Pagle\'a na Przystani Nata na Pyłowym Bagnisku.', '', '', '', '', 0),
(7070, 'koKR', 'Fragmenty odłamka cienia', 'Niedawno zacząłem badać różne kryształy i ich właściwości arkaniczne. Lady Proudmoore pozwoliła mi prosić podróżnych zmierzających do Mrocznego Pustkowia, by odszukali miejsce zwane Maraudon. W zrujnowanej świątyni żyją wielkie żywiołaki zbudowane z fioletowawych kamieni, które nazwałem odłamkami cienia.$B$BJeśli wybierzesz się w tamtą stronę i znajdziesz trochę tych kryształów, będę ci bardzo wdzięczny. Mógłbym nawet wykonać z nich dla ciebie jakąś ozdobę, jeśli zechcesz.', 'Zbierz w Maraudonie 10 fragmentów odłamka cienia i zanieś je arcymagowi Tervoshowi w Theramore, na wybrzeżu Pyłowego Bagniska.', '', 'Wróć do arcymaga Tervosha na Pyłowym Bagnisku.', '', '', '', '', 0),
(8970, 'koKR', 'Widzę w twojej przyszłości Wyspę Alcaz...', 'Jak już mówiłem, za życia myślałem o tym, żeby zostać wróżbitą. Ale nie było w tym tyle zysku, ile można by sądzić, głównie dlatego, że to niebezpieczne, a odczynniki są rzadkie i drogie. Wiem jednak dość, by wskazać ostatni fragment amuletu, a wraz z nim ducha mojego dawnego towarzysza.$B$BI tu wkraczasz ty, $N. Musisz udać się na Wyspę Alcaz u wybrzeży Pyłowego Bagniska i zebrać krwawy wodorost od nag Strashaz, które tam żyją.', 'Zbierz 20 krwawych wodorostów od nag Strashaz, a potem wróć do Bodleya we wnętrzu Czarnej Góry.', '', 'Wróć do Bodleya na Płonących Stepach.', '', '', '', '', 0),
(9437, 'koKR', 'Zmierzch „Biegacza Świtu”', 'Tutejsze ogry nadają się co najwyżej do prostackich żartów, kwaśnego piwa i walenia się łbami. Kiedy mój statek, „Biegacz Świtu”, osiadł na mieliźnie, te kundle z Theramore zabrały mój ładunek i ostatniego ocalałego członka załogi. Dotarłem tu w poszukiwaniu pomocy, ale te nicponie ogry tylko gapiły się na mnie tępo, gdy opowiadałem im swoją historię.$B$BPrzydałaby mi się pomoc kogoś solidnego w odzyskaniu resztek ładunku i uwolnieniu Ithanii z Wieży Północnego Cypla na północnym wschodzie, gdzie trzymają i ją, i ładunek.', 'Odzyskaj ładunek „Biegacza Świtu” dla Balandara Jasnogwiazdy z Paprotni i uwolnij jego pierwszą oficer Ithanię z rąk sił Theramore w Wieży Północnego Cypla.', '', 'Wróć do Balandara Jasnogwiazdy w Paprotni na Pyłowym Bagnisku.', '', 'Uwolnij Ithanię z Wieży Północnego Cypla', '', '', 0),
(11123, 'koKR', 'Oględziny ruin', 'Biedny James nigdy nie doszedł do siebie po zniszczeniu „Cienistego Wypoczynku” i zamordowaniu jego rodziny. Chłopaki i ja robimy, co możemy, żeby odnaleźć potwory, które to zrobiły.$B$BWysłałem do ruin naszego najlepszego śledczego, inspektora Tarema, ale to za duże zadanie dla jednego człowieka. Jeśli pomożesz Taremowi, będziemy wdzięczni. Światłość świadkiem, wszyscy chcielibyśmy tam być i pomagać.$B$BGłówna droga zaprowadzi cię do karczmy, ale uważaj. W tej podróży opuścisz zasięg ochrony moich żołnierzy.', 'Porozmawiaj z inspektorem Taremem przy karczmie „Cienisty Wypoczynek”.', '', '', '', '', '', '', 0),
(11124, 'koKR', 'Oględziny ruin', 'Jeśli pójdziesz drogą na południe od wioski, a potem na zachód w stronę Pustkowi, trafisz na ruiny karczmy „Cienisty Wypoczynek”.$B$BTheramore przysłało śledczego, który ma ustalić, jaki los spotkał karczmę. Normalnie radziłbym trzymać się z daleka, ale mamy rozkazy z Orgrimmaru, by „pomagać” w śledztwie.$B$BPrzyjmij każdą pomoc, jaką zaoferuje śledczy z Theramore, a jeśli chcesz, podrzuć mu nawet okruch informacji albo dwa, ale prawdziwe ustalenia zachowaj dla mnie.', 'Porozmawiaj z inspektorem Taremem przy karczmie „Cienisty Wypoczynek”.', '', '', '', '', '', '', 0),
(11126, 'koKR', 'Zdrajcy wśród nas', 'Miło cię poznać, $N. Przybyłam do Theramore, by pomóc rozwiązać problem dezerterów. Nie dość, że część ludzi porzuciła posterunki, to niektórzy przeniknęli z powrotem do miasta.$B$BCi agenci dezerterów szerzą kłamstwa i propagandę, licząc, że przekonają innych, by przyłączyli się do ich szeregów.$B$BSą praktycznie przy każdym posterunku straży w mieście i w dokach. Znajdź ich, zdemaskuj i ośmiesz. Na tym etapie cokolwiek więcej groziłoby tylko wzbudzeniem większej sympatii dla nich.', 'Zdemaskuj 5 agitatorów dezerterów i wróć do Calii Hastings przy dokach w Theramore.', '', 'Wróć do Calii Hastings na Wyspie Theramore na Pyłowym Bagnisku.', 'Zdemaskowany agitator dezerterów', '', '', '', 0),
(11128, 'koKR', 'Wojna propagandowa', 'Agenci dezerterów robili znacznie więcej, niż tylko zagadywali strażników. Znaleźliśmy sporo ulotek, które dezerterom jakimś cudem udało się przemycić statkiem do doków.$B$BStatek, którym przewieziono ulotki, wciąż stoi w Theramore, przy najdalszym nabrzeżu. Jeśli zdołasz zakraść się na pokład i przejąć resztę ich materiałów propagandowych, ich agenci stracą najpotężniejsze narzędzie. Uważaj! Załogę statku stanowią doświadczeni korsarze, a ładunek jest pewnie trzymany w kajucie kapitana.', 'Przynieś propagandę dezerterów Calii Hastings przy dokach w Theramore.', '', 'Wróć do Calii Hastings na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(11133, 'koKR', 'Ośmieszenie dezerterów', 'Przerobiłam ulotki, które $gzdobyłeś:zdobyłaś; na najemnych kompanach dezerterów w dokach. Teraz każdy, kto je przeczyta, zobaczy dezerterów i ich cele w zupełnie innym świetle.$B$BJeśli rozdamy je wystarczająco wielu strażnikom, dezerterzy będą zbyt skompromitowani, by kiedykolwiek znów zadomowić się w naszych murach.$B$B<Calia wręcza ci plik przerobionych ulotek.>$B$BMoże zaczniesz, a ja w tym czasie zaplanuję nasz następny ruch?', 'Calia Hastings chce, żebyś $grozdał:rozdała; przerobione ulotki 6 strażnikom Theramore, a potem $gzameldował:zameldowała; się u niej przy dokach w Theramore.', '', 'Wróć do Calii Hastings na Wyspie Theramore na Pyłowym Bagnisku.', 'Rozdane ulotki', '', '', '', 0),
(11134, 'koKR', 'Koniec dezerterów', 'Skoro pozbyliśmy się dezerterów z Theramore, czas dokończyć tę operację. Moi miejscowi informatorzy donoszą, że dezerterzy prowadzą działania ze statku zakotwiczonego przy małej wyspie na południowy wschód od doków.$B$BAresztowanie ich przywódcy, Gavisa Szarej Tarczy, powinno odebrać pozostałym wolę walki. Znajdź go na statku i przekonaj, żeby się poddał. Nie zdziwię się, jeśli dla pozoru trochę powalczy, a potem się podda, kiedy zrozumie, że nie wygra.', 'Pojmij Gavisa Szarą Tarczę, a potem zamelduj się u Calii Hastings przy dokach w Theramore.', '', 'Wróć do Calii Hastings na Wyspie Theramore na Pyłowym Bagnisku.', 'Gavis Szara Tarcza pojmany', '', '', '', 0),
(11136, 'koKR', 'Niepokojący obrót spraw', 'Raporty naszych patroli zwiadowczych przybrały ostatnio niepokojący obrót. Mówią o ludziach w czerwonych chustach Nieskornych, którzy chodzą po Wybrzeżu Męciwód na północ od murów Theramore.$B$BSzczątki w okolicy wskazują, że mogą to być rozbitkowie, ale nasze informacje są skąpe. Kapitan Wymor z Posterunku Strażniczego, wieży strażniczej na północ od miasta, szuka pomocy w sprawdzeniu tych doniesień.', 'Zamelduj się u kapitana Wymora na Posterunku Strażniczym.', '', '', '', '', '', '', 0),
(11137, 'koKR', 'Nieskorni na Pyłowym Bagnisku?', 'Moi zwiadowcy donieśli o wraku statku tuż przy plaży na północnym wschodzie. Wraki nie są tu niczym niezwykłym, ale z raportów wynikało też, że wszyscy rozbitkowie nosili czerwone chusty!$B$BNieskorni to rzemieślnicy i członkowie cechów, nie żeglarze. Co robią przy wraku na kontynencie, który ich nie interesuje?$B$BPodobno ich przywódca przebywa na dużej wyspie tuż przy wybrzeżu, na północny wschód od wieży. Zabij go i odbierz mu wszelkie dokumenty, jakie przy sobie ma.', 'Zdobądź rozkazy Nieskornych od Garna Mathersa i zanieś je kapitanowi Wymorowi na Posterunku Strażniczym.', '', 'Wróć do kapitana Wymora na Posterunku Strażniczym na Pyłowym Bagnisku.', '', '', '', '', 0),
(11138, 'koKR', 'Renn McGill', 'Sądząc ze sformułowań odzyskanych przez ciebie rozkazów, pierwszym zadaniem Nieskornych będzie odnalezienie i zabezpieczenie ładunku, który przewozili.$B$BWW:7 ma od pewnego czasu w Theramore nurka ratowniczego, Renna McGilla. Kiedy Renn usłyszał o wraku, wyruszył na północ, by nurkować przy wyspach zajętych teraz przez Nieskornych.$B$BJeśli mamy dotrzeć do tego ładunku przed Nieskornymi, będziemy potrzebowali jego pomocy. Szukaj go w wodach na północny wschód od małej wyspy leżącej tuż na północ od tej, którą wcześniej $godwiedziłeś:odwiedziłaś;.', 'Zanieś rozkazy Nieskornych Rennowi McGillowi w wodach przy Wybrzeżu Męciwód.', '', 'Wróć do Renna McGilla na Wybrzeżu Męciwód na Pyłowym Bagnisku.', '', '', '', '', 0),
(11139, 'koKR', 'Używany sprzęt do nurkowania', 'Na dnie, stąd aż po Alcaz, leży mnóstwo szczątków, a Nieskorni już wysłali tam nurków, żeby się rozejrzeli. Z pomocą części ich sprzętu możemy cię wyekwipować i przygotować do poszukiwań, ale najpierw musisz się wykazać odrobiną twórczego „pożyczania”.$B$BPrzeszukaj tę wyspę i znajdź skrzynię ze sprzętem do nurkowania oraz coś, czym da się go naprawić. Kiedy je zdobędziesz, przynieś mi je, a w mig przygotuję ci sprzęt!', 'Przynieś zestaw narzędzi i uszkodzony sprzęt do nurkowania Rennowi McGillowi na Pyłowym Bagnisku.', '', 'Wróć do Renna McGilla na Wybrzeżu Męciwód na Pyłowym Bagnisku.', '', '', '', '', 0),
(11140, 'koKR', 'Odzyskaj ładunek!', 'Cóż, udało mi się naprawić ten sprzęt na tyle, że przez jakiś czas możesz w nim nurkować. Nie liczyłbym jednak, że długo wytrzyma.$B$BSzczątki statku ciągną się po dnie od wschodniego brzegu tej wyspy aż w stronę Wyspy Alcaz. Dopóki hełm wytrzymuje, odszukaj na dnie kawałki wraku między tą wyspą a Alcaz. Użyj tego zestawu ratowniczego, żeby przeszukać szczątki i znaleźć części ładunku. Uważaj, żeby nie zapuszczać się zbyt blisko Wyspy Alcaz. Tamtejsze hydry są groźne.', 'Przynieś 6 wyłowionych kasetek Rennowi McGillowi na Pyłowym Bagnisku.', '', 'Wróć do Renna McGilla na Wybrzeżu Męciwód na Pyłowym Bagnisku.', '', '', '', '', 0),
(11141, 'koKR', 'Jaina musi się dowiedzieć', 'Musisz bez zwłoki przekazać lady Jainie wieści o naszych odkryciach! Jeśli Nieskorni przewozili więźnia, nie wiadomo, kto to może być ani czy ta osoba jeszcze żyje!$B$BJedno jest pewne, $N. Nieskorni nie zadawaliby sobie tyle trudu z powodu jakiejś błahej urazy. Ich więzień musiał być kimś ważnym. Lady Jaina lepiej niż ktokolwiek zrozumie, co oznaczają te odkrycia. Znajdziesz ją na szczycie wieży magów w centrum Theramore.', 'Porozmawiaj z lady Jainą Proudmoore w Theramore.', '', '', '', '', '', '', 0),
(11142, 'koKR', 'Zbadaj Wyspę Alcaz', 'Wygląda na to, że przeczucie Renna co do Wyspy Alcaz było trafne. Musimy zbadać tę wyspę, ale żeby się tam przebić, potrzebna byłaby cała brygada.$B$BObrona Theramore nie zniosłaby takiego uszczerbku, dlatego umówiłam się z Cassą Karmazynowym Skrzydłem, uczennicą mistrza gryfów z Theramore, że pozwoli ci skorzystać z jednego ze swoich zwierząt, żebyś $gzbadał:zbadała; Alcaz z powietrza.$B$BWyspa Alcaz kryje klucz do zagadki udziału Nieskornych w tym porwaniu.', 'Porozmawiaj z Cassą Karmazynowym Skrzydłem i użyj jednego z jej gryfów, żeby zbadać Wyspę Alcaz. Po zakończeniu rozpoznania porozmawiaj z lady Jainą Proudmoore w Theramore.', 'Zbadaj Wyspę Alcaz', 'Wróć do lady Jainy Proudmoore na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(11143, 'koKR', 'Ponury trop', 'Rozmawiałem z inspektorem Taremem o dowodach, które $gzebrałeś:zebrałaś; w ruinach karczmy „Cienisty Wypoczynek”. Jest pewien, że ślady kopyt i tarcza, które tam $gznalazłeś:znalazłaś;, wskazują na taureński klan Ponurego Totemu.$B$BSkoro coraz częściej słyszymy o poczynaniach Ponurych Totemów na bagnach, to nie może być zwykły zbieg okoliczności. Wysyłam cię do kapitana Darilla, który zna się na Ponurych Totemach jak mało kto. Idź drogą na północ od miasta do Wieży Północnego Cypla. To druga placówka przy drodze.', 'Zamelduj się u kapitana Darilla przy Wieży Północnego Cypla.', '', '', '', '', '', '', 0),
(11144, 'koKR', 'Potwierdzenie podejrzeń', 'Ponure Totemy to może najbardziej wojowniczy ze wszystkich klanów taurenów, ale z pewnością nie brak im organizacji. Jeśli to oni podpalili karczmę „Cienisty Wypoczynek”, musieli dostać rozkazy od któregoś ze starszych klanu.$B$BNa północnym zachodzie leży duża osada Ponurych Totemów, Wioska Czarnego Kopyta. Służy im za bazę do ataków na wieżę, ale założę się, że właśnie tam znajdziesz rozkazy, których szukasz. Sprawdź starszych wioski – może mają przy sobie ślady tych rozkazów.', 'Przynieś plan bitwy Ponurego Totemu kapitanowi Darillowi przy Wieży Północnego Cypla.', '', 'Wróć do kapitana Darilla przy Wieży Północnego Cypla na Pyłowym Bagnisku.', '', '', '', '', 0),
(11145, 'koKR', 'Więźniowie Ponurych Totemów', 'Robimy wszystko, co w naszej mocy, żeby trzymać napastników z Ponurego Totemu na dystans, ale wciąż atakują wieżę. Co gorsza, udało im się wykryć i pojmać patrole, które kapitan wysyła po informacje i dla ochrony drogi.$B$BPodejrzewam, że jeńców przetrzymują w Wiosce Czarnego Kopyta na północnym zachodzie. Znając Ponure Totemy, obrońcy wioski pewnie noszą przy sobie klucze do klatek z więźniami. Nie obchodzi mnie, co będziesz $gmusiał:musiała; zrobić, $N, byle moi ludzie wrócili żywi.', 'Sierżant Lukas przy Wieży Północnego Cypla chce, żebyś $guwolnił:uwolniła; 5 więźniów z Theramore.', '', 'Wróć do sierżanta Lukasa przy Wieży Północnego Cypla na Pyłowym Bagnisku.', 'Uwolnieni więźniowie z Theramore', '', '', '', 0),
(11146, 'koKR', 'Łowy na raptory', 'Kawałek bagna na północnym wschodzie zamieszkuje wyjątkowo paskudna odmiana raptorów. Straciliśmy przez nie niejednego nieostrożnego żołnierza, ale myślę, że możemy je obrócić przeciwko naszym sąsiadom z Ponurego Totemu.$B$BWeź tę linę i użyj jej, żeby schwytać raptory z Krwawych Bagien albo skrzekacze z Krwawych Bagien, które obezwładnisz. Nie próbowałbym chwytać żadnej z tych bestii, dopóki porządnie jej nie osłabisz w walce. To będzie niezła szarpanina.', 'Sierżant Lukas przy Wieży Północnego Cypla chce, żebyś $gschwytał:schwytała; 6 raptorów. Możesz chwytać raptory z Krwawych Bagien albo skrzekacze z Krwawych Bagien.', '', 'Wróć do sierżanta Lukasa przy Wieży Północnego Cypla na Pyłowym Bagnisku.', 'Schwytane raptory', '', '', '', 0),
(11147, 'koKR', 'Wypuść raptory', 'Skoro mamy już raptory, następnym krokiem jest „zachęcić” je do ataku na Ponure Totemy w Wiosce Czarnego Kopyta na północnym zachodzie.$B$BZostał mi udziec z... zresztą nieważne z czego. To będzie twoja przynęta. Połóż go na ziemi w Wiosce Czarnego Kopyta, przy wiatraku w środku osady. Jeśli tresura się udała, raptory zajmą się resztą.', 'Sierżant Lukas przy Wieży Północnego Cypla chce, żebyś $gpołożył:położyła; przynętę na raptora przy wiatraku w Wiosce Czarnego Kopyta.', '', 'Wróć do sierżanta Lukasa przy Wieży Północnego Cypla na Pyłowym Bagnisku.', 'Wypuszczone raptory', '', '', '', 0),
(11148, 'koKR', 'Uzbrojenie Ponurych Totemów', 'Jeśli ekwipunek, który $gznalazłeś:znalazłaś; w ruinach karczmy, należał do oddziału szturmowego Ponurych Totemów, w ich obozie na północnym zachodzie pewnie jest więcej takiego samego.$B$BNie zdołaliśmy zebrać wielu informacji o Wiosce Czarnego Kopyta, ale sądząc po liczebności oddziałów najeźdźców, stacjonują tam znaczne siły.$B$BZrób, co musisz, żeby zdobyć część ich ekwipunku, abyśmy mogli porównać go z tym, co $gznalazłeś:znalazłaś; przy karczmie.', 'Kapitan Darill przy Wieży Północnego Cypla chce, żebyś $gprzyniósł:przyniosła; mu 7 sztuk uzbrojenia Czarnego Kopyta.', '', 'Wróć do kapitana Darilla przy Wieży Północnego Cypla na Pyłowym Bagnisku.', '', '', '', '', 0),
(11149, 'koKR', 'Pomoc Tabethy', 'Nie mogę oddelegować żadnych ludzi do szukania drugiej placówki Ponurych Totemów, ale chyba wiem, kto mógłby ci pomóc.$B$BW głębi Torfowiska, na południu, jest małe gospodarstwo należące do Tabethy. Może się wydawać zwykłą starą pustelnicą, ale w rzeczywistości to magini i jasnowidzka o sporej renomie. Idź drogą na południe do jej farmy i poproś ją o pomoc w odnalezieniu winnych masakry w karczmie „Cienisty Wypoczynek”.', 'Porozmawiaj z Tabethą na jej farmie.', '', '', '', '', '', '', 0),
(11150, 'koKR', 'Spal Posterunek Złorożców!', 'Nie trzeba żadnego wróżenia, żeby zobaczyć, jakie kłopoty sprawiają moi nowi „sąsiedzi”. A jeśli to ta banda spaliła karczmę „Cienisty Wypoczynek”, jak twierdzisz, nie ma powodu dłużej tolerować ich obecności.$B$BWeź tę pochodnię i zrównaj ich obóz z ziemią! Posterunek Złorożców znajdziesz tuż na północ od mojej farmy. Naprawdę nie da się go przeoczyć, bo Ponure Totemy znakomicie obwieściły swoją obecność tymi totemami, które tak lubią.', 'Spal północny, wschodni i północno-wschodni namiot w Posterunku Złorożców, a potem wróć do Tabethy na jej farmie.', '', 'Wróć do Tabethy na Farmie Tabethy na Pyłowym Bagnisku.', 'Spalony północny namiot', 'Spalony północno-wschodni namiot', 'Spalony wschodni namiot', '', 0),
(11151, 'koKR', 'Sprawiedliwość dla Hyalów', 'Choć te Ponure Totemy były dla mnie tylko utrapieniem, kapitan Vimes zechce się dowiedzieć o twoich czynach. Zanieś mu wieść, że $gwytropiłeś:wytropiłaś; i $gukarałeś:ukarałaś; winnych spalenia karczmy „Cienisty Wypoczynek”.$B$BNa ratunek dla rodziny Jima Hyala jest już za późno, ale może Ponure Totemy dwa razy się zastanowią, zanim zaatakują kogokolwiek związanego z Theramore.', 'Porozmawiaj z kapitanem Garranem Vimesem w Cytadeli Przyczółku w Theramore.', '', '', '', '', '', '', 0),
(11152, 'koKR', 'Wreszcie spokój', 'Szkoda, że nie możemy jakoś dać znać żonie i synowi Jamesa Hyala, że ich mordercy ponieśli karę.$B$B<Kapitan Vimes wyjmuje mały wieniec ozdobiony kwiatami.>$B$BNiektórzy mówią, że ich duchy się dowiedzą, nawet jeśli nie możemy do nich dotrzeć. To niewiele, ale chciałbym, żebyś $gzłożył:złożyła; ten wieniec pod pomnikiem rodziny Hyal. To jeden z większych kamieni na cmentarzu tuż na północ od bram Theramore.', 'Kapitan Garran Vimes w Cytadeli Przyczółku chce, żebyś $gzłożył:złożyła; wieniec pod pomnikiem rodziny Hyal.', '', 'Wróć do kapitana Garrana Vimesa w Cytadeli Przyczółku na Pyłowym Bagnisku.', 'Wieniec złożony pod pomnikiem Hyalów', '', '', '', 0),
(11156, 'koKR', 'Najeźdźcy z Posterunku Złorożców', 'Ponure Totemy z Posterunku Złorożców, tuż na północy, z każdym dniem stają się śmielsze. Nocami często słychać, jak śpiewają o swoich czynach w walce z tymi, którzy próbowali się tu osiedlić.$B$BZa wszelką cenę chcą nas przegnać z farmy Tabethy, choć ona szkoli tu uczniów od pokoleń. Bronimy farmy, jak możemy, ale w ostatnim ataku ranny został uczeń Garion.$B$BIdź do Posterunku Złorożców i wybij wszystkie Ponure Totemy, jakie znajdziesz! Te ataki muszą się skończyć.', 'Zabij 12 Ponurych Totemów z Posterunku Złorożców i wróć do ucznia Morlanna na Farmie Tabethy.', '', 'Wróć do ucznia Morlanna na Farmie Tabethy na Pyłowym Bagnisku.', 'Zabite Ponure Totemy z Posterunku Złorożców', '', '', '', 0),
(11158, 'koKR', 'Pióra z Krwawych Bagien', 'Dziwić cię, że Brogg tu jest, maluchu? Nie bój się. Gobliny w Zębłotce to przyjaciele Brogga, ty też możesz być.$B$BBrogg odejść z Paprotni, kiedy nowy nadrządca nie zemścić się na czarnych drakanach za zniszczenie starego domu i zabicie wielu starych przyjaciół Brogga. Brogg przyjść tu dać spokój duchom przyjaciół i pomścić ich, ale Brogg potrzebować pomocy w przygotowaniach. Do rytuału Brogg potrzebować piór z silną magią, takich jak u raptorów w Norze Krwawych Bagien na zachód od miasta.', 'Przynieś 5 piór z Krwawych Bagien Broggowi w Zębłotce.', '', 'Wróć do Brogga w Zębłotce na Pyłowym Bagnisku.', '', '', '', '', 0),
(11159, 'koKR', 'Duchy Warowni Kamiennych Maczug', 'Brogg skończył totem, który da spokój duchom jego przyjaciół. Kiedy przyszły drakanie, zabili wszystkich z Kamiennych Maczug, którzy nie uciekli. Brogg uciekł z nadrządcą Mok\'Morokkiem w nadziei, że poprowadzi kontratak z innymi ocalałymi z Kamiennych Maczug.$B$BKontratak nigdy nie nastąpił, a duchy poległych z Kamiennych Maczug wciąż nawiedzają Brogga i innych. Zanieś ten totem na północ, do Ruin Kamiennych Maczug, i użyj go przy szkieletach ogrów, żeby przywołać do siebie ducha. Pokonaj ducha, żeby spoczął w pokoju razem ze swoimi kośćmi.', 'Brogg z Zębłotki chce, żebyś $gzapewnił:zapewniła; wieczny spoczynek 10 duchom Kamiennych Maczug.', '', 'Wróć do Brogga w Zębłotce na Pyłowym Bagnisku.', 'Duchy Kamiennych Maczug ukojone', '', '', '', 0),
(11160, 'koKR', 'Sztandar Kamiennych Maczug', 'Kiedy smoki przyszły i zajęły stary dom Brogga, ogry z Kamiennych Maczug uciekły i zostawiły wszystko, nawet sztandar klanu.$B$BBrogg wie, że sztandar trzymano głęboko w kopcu ogrów z Kamiennych Maczug, ale teraz to miejsce nazywa się Nora Płomienia. Brogg musi mieć sztandar klanu, żeby zemścić się na smokach, które zabiły jego przyjaciół.$B$BStary kopiec klanu Brogga, Nora Płomienia, jest na północny zachód od Zębłotki i roi się tam od drakanów. Sztandar będzie głęboko w jaskini. Uważaj, $N.', 'Odzyskaj sztandar Kamiennych Maczug i zanieś go Broggowi w Zębłotce.', '', 'Wróć do Brogga w Zębłotce na Pyłowym Bagnisku.', '', '', '', '', 0),
(11161, 'koKR', 'Esencja wrogości', 'Żeby zrobić totem potrzebny do rytuału, Brogg musi użyć esencji stworzeń, które zabiły jego przyjaciół. Nienawiść i gniew wrogów Brogga napędzą magię jego zemsty.$B$BWytrop popielne ogony, zwiadowców albo zgubołuski Ognistej Grzywy i użyj totemu Brogga na ich zwłokach. Drakanie oddadzą swoje esencje dopiero po śmierci.$B$BStwory, których szukasz, roją się w Norze Płomienia na północnym zachodzie i w Ruinach Kamiennych Maczug na północy.', 'Przynieś 10 esencji czarnego drakanina Broggowi w Zębłotce.', '', 'Wróć do Brogga w Zębłotce na Pyłowym Bagnisku.', '', '', '', '', 0),
(11162, 'koKR', 'Wyzwanie dla Czarnego Stada', 'Brogg rozkoszuje się myślą o zemście na czarnych drakanach z bagien. $N, bardzo $gpomogłeś:pomogłaś; w przygotowaniach do tej chwili. Pomożesz?$B$BWeź sztandar klanu Brogga i idź na wschód, aż zobaczysz jaskinię podobną do smoczej paszczy. Przy wejściu do tej jaskini zatknij sztandar Kamiennych Maczug i rzuć Onyxii wyzwanie od Brogga.$B$BBrogg i Kamienne Maczugi odzyskają swoje ziemie!', 'Zatknij sztandar Kamiennych Maczug przy wejściu do Leża Onyxii, poczekaj na odpowiedź Onyxii, a potem wróć do Brogga w Zębłotce.', '', 'Wróć do Brogga w Zębłotce na Pyłowym Bagnisku.', 'Klan Kamiennych Maczug pomszczony', '', '', '', 0),
(11169, 'koKR', 'Broń Ponurych Totemów', 'Podczas ostatniego ataku Ponurych Totemów zostałem ranny, ale wcześniej zdołałem przejąć dziwny totem, którego wrogowie używali przeciwko nam.$B$BW czasie bitwy zdawał się ciskać surowymi wyładowaniami energii, ale mimo wszystkich eksperymentów nie udało mi się ustalić, jak działa. Pożyczę ci ten totem, jeśli zgodzisz się pomóc mi go przetestować.$B$BW podmokłych okolicach farmy żyją uciążliwe cętkowane suchobagienne krokoliszki i suchobagienne sztyletopaszcze. Spróbuj walczyć z krokoliszkami w pobliżu totemu.', 'Uczeń Garion na Farmie Tabethy chce, żebyś $gprzetestował:przetestowała; zdobyczny totem na 10 cętkowanych suchobagiennych krokoliszkach lub suchobagiennych sztyletopaszczach.', '', 'Wróć do ucznia Gariona na Farmie Tabethy na Pyłowym Bagnisku.', 'Przeprowadzone testy totemu', '', '', '', 0),
(11172, 'koKR', 'Katastrofa sterowca', 'Niedawno na wschodzie rozbił się gobliński sterowiec. Kilka dni temu przechodziła tędy przedstawicielka Kartelu Parochlebców.$B$BSzukała informacji o ładunku sterowca i jego pilocie, Beezilu, ale nikt z nas nie przyjrzał się dobrze katastrofie. Wątpię, żeby sama zdołała uprzątnąć wrak, a co dopiero odzyskać ładunek, który mógł przewozić statek.$B$BJeśli masz czas, może zajrzysz do niej przy Wraku Beezila, prosto na wschód stąd, blisko gór.', 'Porozmawiaj z Moxie Steelgrille przy Wraku Beezila.', '', '', '', '', '', '', 0),
(11173, 'koKR', 'Złodziej składników', 'Jeśli na coś można liczyć u ucznia Morlanna, to na marudzenie o składnikach.$B$BZwykle po prostu go ignoruję i to nigdy nie działa. Tym razem spróbuję czegoś innego.$B$BMoże jeśli uzupełnię brakujące składniki, zanim się zorientuje, da mi spokój. Składnik, którego obaj używamy najczęściej, to bagienny jad, pozyskiwany z mrocznokłych pełzaczy i trujących rozszarpywaczy z bagien na północ od farmy. Jeśli przyniesiesz mi jad, uzupełnię zapas, zanim Morlann zauważy, że zniknął.', 'Przynieś 6 fiolek bagiennego jadu uczniowi Garionowi na Farmie Tabethy.', '', 'Wróć do ucznia Gariona na Farmie Tabethy na Pyłowym Bagnisku.', '', '', '', '', 0),
(11174, 'koKR', 'Zapobieganie korozji', 'Tylko spójrz na tę okolicę! Roi się od szlamów. Jeśli nie znajdę sposobu, żeby utrzymać je w ryzach, przeżrą wrak i ładunek sterowca!$B$BNie mogę wrócić z pustymi rękami, $N! Pomóż mi rozpuścić te szlamy, zanim wszystko strawią!$B$BTo urządzenie, gdy jest zasilane, skupia energię na szlamach i sprawia, że wybuchają. Powinny je zasilić fragmenty rdzenia zasilającego sterowca. Ten przy głównym miejscu katastrofy działa cały czas, ale pozostałe to się włączają, to wyłączają.', 'Moxie Steelgrille chce, żebyś $grozpuścił:rozpuściła; 10 szlamów i $gzameldował:zameldowała; się u niej przy Wraku Beezila.', '', 'Wróć do Moxie Steelgrille przy Wraku Beezila na Pyłowym Bagnisku.', 'Rozpuszczone szlamy', '', '', '', 0),
(11177, 'koKR', 'Pustelnik z Dworu Bagiennego Światła', 'Mieszka tu taki gość, którego miejscowi znają jako „Bagienne Oko” Jarl. Żyje sam na bagnach. Jakiś czas temu „przejął” Dwór Bagiennego Światła, kiedy poprzedni właściciele zniknęli w tajemniczych okolicznościach.$B$BLubię co jakiś czas wysłać kogoś, żeby do niego zajrzał. Trochę przypomina mi mojego dziadka, wiesz? Niektórzy mówią, że ma nie po kolei w głowie.$B$BJeśli pójdziesz drogą z Theramore na północny zachód, znajdziesz Dwór Bagiennego Światła na Wzgórzu Czarownic, zanim droga skręci na zachód.', 'Porozmawiaj z „Bagiennym Okiem” Jarlem we Dworze Bagiennego Światła.', '', '', '', '', '', '', 0),
(11180, 'koKR', 'Co nawiedza Wzgórze Czarownic?', 'Przyjechałem tu odwiedzić Jarla w jego nowym domu i od tamtej pory to jeden nieustający horror! Dzieje się tu coś bardzo złego i nie mogę być jedynym, który to widzi...$B$B$GWidziałeś:Widziałaś; duchy i trupy snujące się po Wzgórzu Czarownic? Mam przeczucie, że jeśli ktokolwiek wie, co się tu stało, to właśnie one. Odszukaj w okolicy te powstałe skorupy i powstałe duchy, daj im spokój w walce i zobacz, czego możesz się od nich dowiedzieć, zanim to zło pochłonie Jarla!', 'Mordant Grimsby we Dworze Bagiennego Światła chce, żebyś $gzebrał:zebrała; informacje od 10 powstałych skorup lub powstałych duchów.', '', 'Wróć do Mordanta Grimsby\'ego we Dworze Bagiennego Światła na Pyłowym Bagnisku.', 'Zebrane informacje', '', '', '', 0),
(11181, 'koKR', 'Wiedźmia zguba', 'Przez lata pracy jako zielarz często zauważałem, że natura dostarcza subtelnych lekarstw na najbardziej dokuczliwe problemy. Czytałem, że wiejscy magowie i znachorzy często używają dymu z ziela zwanego wiedźmią zgubą, żeby wywabić zło z kryjówek.$B$BJeśli to prawda, wiedźmia zguba powinna rosnąć przy płytkich wodach Wzgórza Czarownic. Rozpoznasz ją po szerokich liściach i czerwonawej łodydze pośrodku. Przynieś mi tyle tego ziela, ile znajdziesz, $N. To może być nasza jedyna nadzieja.', 'Przynieś 9 gałązek wiedźmiej zguby Mordantowi Grimsby\'emu we Dworze Bagiennego Światła.', '', 'Wróć do Mordanta Grimsby\'ego we Dworze Bagiennego Światła na Pyłowym Bagnisku.', '', '', '', '', 0),
(11183, 'koKR', 'Oczyszczenie Wzgórza Czarownic', 'Pochodnia gotowa. Zatknij ją na końcu pomostu i bądź $ggotów:gotowa; stawić czoła temu, co się pojawi.$B$BNie mam pojęcia, co może ujawnić dym z pochodni... i czy w ogóle coś się pojawi. Muszę przyznać, że mam wątpliwości co do takiej ludowej magii, ale nie mamy czasu na nic innego. Życzę ci powodzenia, przez wzgląd na ciebie i na Jarla.', 'Mordant Grimsby we Dworze Bagiennego Światła chce, żebyś $gzatknął:zatknęła; pochodnię na końcu pomostu i $gpokonał:pokonała; wszystko, co się pojawi.', '', 'Wróć do Mordanta Grimsby\'ego we Dworze Bagiennego Światła na Pyłowym Bagnisku.', 'Wzgórze Czarownic oczyszczone', '', '', '', 0),
(11184, 'koKR', 'POSZUKIWANY: Krwiopazur Wygłodniały', 'Podróżnym i pracownikom Parochlebców pracującym w terenie zaleca się unikanie Nory Krwawych Bagien na zachód od miasta.$B$BOkolicę opanowały raptory, którymi przewodzi okrutny i przebiegły Krwiopazur Wygłodniały. Zabił już co najmniej dwóch inżynierów Parochlebców.$B$BDrazzit Kapizawór zatwierdził sowitą nagrodę dla osoby, która uwolni Zębłotkę od tego zagrożenia.', 'Zabij Krwiopazura Wygłodniałego i zamelduj się u Drazzita Kapizawora w Zębłotce.', '', 'Wróć do Drazzita Kapizawora w Zębłotce na Pyłowym Bagnisku.', '', '', '', '', 0),
(11185, 'koKR', 'List aptekarki', 'Ten list, zabrany z ciała aptekarki Porzuconych, zawiera niepokojące dowody bliskiego sojuszu między Ponurymi Totemami a nowymi panami Lordaeronu.$B$B„Na dowód dobrej woli i jako symbol nowo zawiązanego zaufania wysłaliśmy aptekarkę Cyllę, by pomogła wam w walce z naszym wspólnym wrogiem w krainie Kalimdor. Nikt nie oprze się naszej połączonej potędze i determinacji”.$B$BTen list należy przekazać agentowi WW:7 na Farmie Tabethy, Andellowi Porterowi.', 'Zanieś zapieczętowany list Andellowi Porterowi na Farmie Tabethy.', '', 'Wróć do Andella Portera na Torfowisku na Pyłowym Bagnisku.', '', '', '', '', 0),
(11186, 'koKR', 'Oznaki zdrady?', 'Ten list, znaleziony przy zwłokach aptekarki Porzuconych, sugeruje, że Podmiasto i przywódcy Ponurych Totemów prowadzą potajemną korespondencję.$B$B„Na dowód dobrej woli i jako symbol świeżo zrodzonego zaufania wysłaliśmy aptekarkę Cyllę, by wspomogła was w walce z naszym wspólnym wrogiem na ziemiach Kalimdoru. Nikt nie oprze się naszej połączonej potędze i determinacji”.$B$BByć może Nazeer Krwawa Pika w Paprotni będzie wiedział, co zrobić z tą informacją.', 'Zanieś zapieczętowany list Nazeerowi Krwawej Pice w Paprotni.', '', '', '', '', '', '', 0),
(11191, 'koKR', 'Stara latarnia morska', 'Stara latarnia morska na wschodzie od dawna nie działa, ale Babs Fizzletorque uparła się, żeby ją znowu uruchomić.$B$BNie wiem, jak zamierza to zrobić sama, ale twierdzi, że dzięki temu statki i towary będą sprawniej trafiać do doków, więc nie bardzo mogę protestować. Służba w dokach to naprawdę nic, na co można narzekać, kiedy równie dobrze można by trafić na pierwszą linię frontu, wiesz?', 'Porozmawiaj z Babs Fizzletorque w latarni morskiej na wyspie na wschód od Theramore.', '', '', '', '', '', '', 0),
(11192, 'koKR', 'Olej z młocarza', 'Według starego dziennika latarni lampę zasilano olejem z młocarzy, które żyją wzdłuż tutejszego wybrzeża.$B$B<Babs marszczy nos na wzmiankę o tak przestarzałej technologii.>$B$BCóż, to rozwiązanie praktyczne, choć mało eleganckie. W dzienniku napisano, że najlepiej sprawdza się olej z najmłodszych mętnych młocarzy, a te żyją tuż pod dokami Theramore.$B$BJeśli masz ochotę, pomożesz uzupełnić zapas paliwa w latarni?', 'Przynieś 4 pojemniki oleju z młocarza Babs Fizzletorque w latarni morskiej koło Theramore.', '', 'Wróć do Babs Fizzletorque na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(11193, 'koKR', 'Podli mieszkańcy głębin', 'Wiesz, to niesamowite, co można znaleźć w tej starej latarni. Kiedy zapaliłam lampę, zauważyłam tę książkę w jednym ze starych kufrów na górze.$B$B<Babs unosi książkę i teatralnie odczytuje tytuł.>$B$B„Podli mieszkańcy głębin!”$B$BOch, chyba bym zemdlała, gdybym kiedyś zobaczyła któregoś z nich! Na pewno można się przy niej nieźle pośmiać, ale teraz zwyczajnie nie mam czasu na czytanie.$B$BWiesz, komu mogłaby się spodobać... temu handlarzowi rybami w dokach, „Brudnemu” Michaelowi Crowe\'owi. Zbiera stare książki.', 'Zanieś książkę „Podli mieszkańcy głębin” „Brudnemu” Michaelowi Crowe\'owi w dokach Theramore.', '', 'Porozmawiaj z „Brudnym” Michaelem Crowe\'em na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(11194, 'koKR', 'Czy to prawda?', 'Och, na pewno ty i Babs nieźle się uśmialiście z tych dziwacznych opisów i szkiców w książce, ale czy $gpomyślałeś:pomyślałaś; choć przez chwilę, że w tych legendach może być ziarno prawdy?$B$BJeśli dobrze się wsłuchasz, założę się, że wciąż usłyszysz, jak żeglarze gadają o Tethyrze, morskim stworze, który według książki żyje właśnie tutaj! Oczywiście, jeśli chcesz wiedzieć na pewno, zawsze możesz zapytać starego Nata Pagle\'a.$B$BMa mały obóz rybacki na wysepce w Zatoczce Furii Przypływu, na południowy zachód stąd, po drugiej stronie Pyłowej Zatoki.', 'Porozmawiaj z Natem Pagle\'em na Przystani Nata na Pyłowym Bagnisku.', '', '', '', '', '', '', 0),
(11198, 'koKR', 'Pokonaj Tethyra!', 'Potwór morski czy nie, nie będziemy narażać bezpieczeństwa naszej żeglugi. Rozkazałem naszym najlepszym strzelcom wyborowym przygotować się do starcia z tym Tethyrem. Artylerzyści wzmocnili obronę doków trzema moździerzami.$B$BRozkażę zapalić lampę w latarni. Jeśli Tethyr zaatakuje, twoim zadaniem będzie obsługa moździerzy i powalenie bestii, zanim zabije wszystkich strzelców. Na twoim miejscu nie stałbym jednak zbyt długo w jednym miejscu. Strzelanie z moździerzy pewnie ściągnie na ciebie jego uwagę.', 'Major Mills w dokach Theramore chce, żebyś $gpokonał:pokonała; Tethyra.', 'Obroń doki Theramore przed Tethyrem', 'Wróć do majora Millsa na Wyspie Theramore na Pyłowym Bagnisku.', '', '', '', '', 0),
(11200, 'koKR', 'Więcej niż zbieg okoliczności', 'Wyciągnęliśmy z ruin karczmy tyle, ile się dało. Niepokoi mnie, dokąd teraz zaprowadzi nas śledztwo, ale musimy poznać prawdę.$B$BŚlady kopyt i tarcza ze znakiem Mosarna każą mi sądzić, że mogły być w to zamieszane Ponure Totemy. Niedawno założyły na bagnach osadę – Wioskę Czarnego Kopyta na północnym wschodzie. Udaj się do Wioski Czarnego Kopyta i poszukaj kolejnych sztuk uzbrojenia wykonanych przez Mosarna.', 'Przynieś Krogowi w Paprotni 7 sztuk uzbrojenia Czarnego Kopyta.', '', 'Wróć do Kroga w Paprotni na Pyłowym Bagnisku.', '', '', '', '', 0),
(11201, 'koKR', 'Spisek Ponurego Totemu', 'Odkąd wyszły na jaw poczynania Ponurych Totemów w Tysiącu Filarów, wielu taurenów patrzy na nie podejrzliwie. Widzieliśmy już, jak wysocy rangą członkowie Ponurego Totemu posuwają się do morderstw i porwań, by osiągnąć swoje cele, i obawiam się, że możemy być następni.$B$BWioska Czarnego Kopyta na północnym wschodzie, niedaleko Niebieskiego Mokradła, to duża nowa osada Ponurych Totemów. Ich przywódcy, starsi, na pewno mają rozkazy z Gromowych Urwisk. Spróbuj zdobyć te rozkazy i złożyć je w całość, by poznać plany Ponurych Totemów.', 'Przynieś plan bitwy Ponurego Totemu Krogowi w Paprotni.', '', 'Wróć do Kroga na Pyłowym Bagnisku.', '', '', '', '', 0),
(11203, 'koKR', 'Odszukaj Tabethę', 'Uzbrojenie, które $gzdobyłeś:zdobyłaś; w Wiosce Czarnego Kopyta, nie widziało żadnej walki poza zwykłymi ćwiczeniami, a to znaczy, że Ponure Totemy, które zniszczyły „Cienisty Wypoczynek”, wciąż są na wolności.$B$BNa południu, w sercu Torfowiska, mieszka wiedźma Tabetha. Choć jest człowiekiem, postępowała wobec nas honorowo i wyszkoliła kilku naszych magów.$B$BPoproś ją o pomoc w wytropieniu bandy Ponurych Totemów odpowiedzialnej za spalenie karczmy. Przymierze nie może uznać, że byliśmy współwinni tego ataku.', 'Porozmawiaj z Tabethą na jej farmie na Torfowisku.', '', '', '', '', '', '', 0),
(11205, 'koKR', 'Spal Posterunek Złorożców!', 'Nie trzeba żadnego wróżenia, żeby zobaczyć, jakie kłopoty sprawiają moi nowi „sąsiedzi”. A jeśli to ta banda spaliła karczmę „Cienisty Wypoczynek”, jak twierdzisz, nie ma powodu dłużej tolerować ich obecności.$B$BWeź tę pochodnię i zrównaj ich obóz z ziemią! Posterunek Złorożców znajdziesz tuż na północ od mojej farmy. Naprawdę nie da się go przeoczyć, bo Ponure Totemy znakomicie obwieściły swoją obecność tymi totemami, które tak lubią.', 'Spal północny, wschodni i północno-wschodni namiot w Posterunku Złorożców, a potem wróć do Tabethy na jej farmie.', '', 'Wróć do Tabethy na Farmie Tabethy na Pyłowym Bagnisku.', 'Spalony północny namiot', 'Spalony północno-wschodni namiot', 'Spalony wschodni namiot', '', 0),
(11206, 'koKR', 'Sprawiedliwość wymierzona', 'Wątpię, by Ponure Totemy zrezygnowały z prób wypędzenia ludzi z bagien. Przynajmniej rozprawiliśmy się ze sprawcami zbrodni w karczmie „Cienisty Wypoczynek”.$B$BŚledczy, który cię przysłał, na pewno wie to i bez mojego gadania, ale Hordy nie stać już na to, by nie okiełznać Ponurych Totemów. Przyjdzie dzień, gdy ich czyny postawią Hordę w godnym pożałowania położeniu.$B$BAni lady Jaina, ani wódz Thrall nie pragną kolejnej wojny, ale czy są gotowi zrobić to, co konieczne, by jej uniknąć?', 'Wróć do Kroga w Paprotni.', '', '', '', '', '', '', 0),
(11207, 'koKR', 'Zabezpiecz ładunek!', 'Ten sterowiec wiózł nam do Zębłotki zapasy na pół roku! Jasne, udało im się wytargować trochę tego, czego potrzebują, ale nie wytrzymają tak w nieskończoność.$B$BPrzysłano mnie tu, żebym odzyskała, co się da z ładunku, ale szczątki są rozrzucone po całych okolicznych bagnach. Pewnie spora część ładunku nie przetrwała katastrofy, ale pomożesz mi odzyskać to, co się da?', 'Moxie Steelgrille przy Wraku Beezila chce, żebyś $godzyskał:odzyskała; 8 sztuk ładunku sterowca.', '', 'Wróć do Moxie Steelgrille przy Wraku Beezila na Pyłowym Bagnisku.', '', '', '', '', 0),
(11208, 'koKR', 'Dostawa dla Drazzita', 'Drazzit będzie czekał na wieści ode mnie, ale nie sądzę, żeby to miejsce było na tyle bezpieczne, żebym mogła je zostawić. Jeśli masz czas, zaniesiesz mu część odzyskanego ładunku do Zębłotki?$B$BJeśli jeszcze tam nie $gbyłeś:byłaś;, to mała osada na południowy zachód stąd, za Ruinami Kamiennych Maczug. Można tam też dojść drogą od Farmy Tabethy. Kiedy dotrzesz do Zębłotki, szukaj Drazzita Kapizawora.', 'Zanieś ładunek sterowca Drazzitowi Kapizaworowi w Zębłotce.', '', 'Wróć do Drazzita Kapizawora w Zębłotce na Pyłowym Bagnisku.', '', '', '', '', 0),
(11209, 'koKR', 'Umowa Nata', 'Więc $gznalazłeś:znalazłaś; egzemplarz „Podłych mieszkańców głębin”, co? Cóż, mogę ci powiedzieć z doświadczenia, że to wszystko prawda. Kilka z nich widziałem nawet na własne oczy.$B$BAle ty chcesz się dowiedzieć czegoś o Tethyrze. Obiecałem ci umowę, więc oto, co masz zrobić. Pracuję nad nową serią przynęt, ale tej jeszcze nie testowałem.$B$BPo prostu weź tę pastę – tak, trochę śmierdzi – wysmaruj się nią i popłyń do tego wraku statku na południowym zachodzie. Jeśli przeżyjesz, daj znać, jak działa!', 'Nat Pagle na Przystani Nata chce, żebyś $gprzetestował:przetestowała; jego nową przynętę na ryby.', '', 'Wróć do Nata Pagle\'a na Przystani Nata na Pyłowym Bagnisku.', 'Przetestowana pasta rybna', '', '', '', 0),
(11210, 'koKR', 'Och, to prawda', 'Tak, Tethyr z całą pewnością istnieje i żyje w wodach u wybrzeży Theramore.$B$BMa słabość do jasnych świateł. To przez niego w ogóle wyłączono latarnię morską, wiesz...$B$BA jeśli znowu ją zapalisz, od razu wróci. Ale nikt przy zdrowych zmysłach by tego nie zrobił.$B$BWięc to musi być twój plan! Miło było się z tobą napić, ale nie miej pretensji do starego Nata, jeśli Tethyr NAPRAWDĘ zrobi z ciebie przynętę na ryby. Jeśli masz zamiar to zrobić, koniecznie porozmawiaj z majorem Millsem w dokach Theramore.', 'Porozmawiaj z majorem Millsem w dokach Theramore.', '', '', '', '', '', '', 0),
(11211, 'koKR', 'Pomoc dla Zębłotki', 'Kiedy ta goblinka... jak jej tam... Boxie, Foxy... Moxie, o właśnie! No więc kiedy przechodziła tędy w drodze do wraku sterowca, mówiła, że miasteczko Zębłotka ma jakieś kłopoty.$B$BTen rozbity sterowiec wiózł im świeże zapasy. Jeśli pójdziesz stąd drogą na południe, za Ruiny Kamiennych Maczug, w końcu dotrzesz do Zębłotki.$B$BMoże zajrzysz tam do Drazzita Kapizawora i sprawdzisz, czy możesz jakoś pomóc?', 'Porozmawiaj z Drazzitem Kapizaworem w Zębłotce.', '', '', '', '', '', '', 0),
(11212, 'koKR', 'Farma Tabethy', 'W samym sercu bagien mieszka stara kobieta imieniem Tabetha. Nigdy nie wiedzieliśmy o niej zbyt wiele, poza tym, że jest dużo starsza, niż wygląda. Od czasu do czasu nam pomagała i przyczyniła się do utrzymania pokoju między Hordą a naszymi siłami.$B$BKiedyś regularnie się z nami kontaktowała, ale ostatnio nie dostaliśmy od niej żadnej wiadomości.$B$B$GMógłbyś:Mogłabyś; do niej zajrzeć, kiedy znajdziesz czas? Po prostu idź drogą za Wieżę Północnego Cypla, tam gdzie skręca na południe, w stronę Torfowiska. Jej farmę widać z drogi.', 'Porozmawiaj z Tabethą na jej farmie na Torfowisku.', '', '', '', '', '', '', 0),
(11213, 'koKR', 'Zajrzyj do Tabethy', 'Na małej farmie w pobliżu środka bagien mieszka ludzka kobieta imieniem Tabetha. Zwykle nie zadawałbym się z człowiekiem, ale jej pomoc bywała przydatna.$B$BNiestety od dłuższego czasu nie daje znaku życia, więc szukam kogoś, kto wybierze się na jej farmę i sprawdzi, czy wszystko w porządku.$B$BJeśli pójdziesz drogą na południe od wioski, a potem w głąb bagien, znajdziesz jej farmę niedaleko środka Torfowiska.', 'Porozmawiaj z Tabethą na jej farmie na Torfowisku.', '', '', '', '', '', '', 0),
(11214, 'koKR', 'Wyprawa do Zębłotki', 'Kartel Parochlebców założył niedawno nową placówkę w południowej części Pyłowego Bagniska. Jeśli dobrze pamiętam, nazywa się Zębłotka i leży przy głównej drodze na południe od Farmy Tabethy i Ruin Kamiennych Maczug.$B$BTo świetna okazja do nawiązania nowych kontaktów handlowych, a lady Jaina chce, żebym wysłał tam przedstawiciela, który nawiąże kontakt. Zgodzisz się pojechać?', 'Porozmawiaj z Drazzitem Kapizaworem w Zębłotce.', '', '', '', '', '', '', 0),
(11215, 'koKR', 'Pomóż Zębłotce', 'Nowa placówka Kartelu Parochlebców w południowej części bagien nie radzi sobie najlepiej. Sterowiec wiozący zaopatrzenie do Zębłotki rozbił się, zostawiając ich bez niezbędnych narzędzi, żywności i środków medycznych.$B$BIdź drogą na południe, w głąb bagien. Miniesz Farmę Tabethy i Ruiny Kamiennych Maczug, zanim droga doprowadzi cię do Zębłotki. Zaoferuj władzom miasteczka wszelką pomoc, jakiej możesz udzielić.', 'Porozmawiaj z Drazzitem Kapizaworem w Zębłotce.', '', '', '', '', '', '', 0),
(11217, 'koKR', 'Złap smoka za ogon', 'Przez katastrofę sterowca dostawy się opóźniają i skończyły nam się leki i bandaże.$B$BRadzimy sobie, jak możemy, ale przy tych wszystkich owadach, ranach i wrogach, na których tu trafiamy, ledwie nadążam! Znalazłem jedno ziele, które chyba pomaga goić rany i łagodzi ból, ale jego też brakuje.$B$BNazywa się żmijogon i rośnie obficie w Smoczym Mroku i na Żmijowym Trzęsawisku na wschód od miasta. Rośliny mają skręcone łodygi i zdają się pulsować, kiedy się na nie patrzy.', 'Gizzix Grimegurgle z Zębłotki chce, żebyś $gprzyniósł:przyniosła; mu 8 łodyg żmijogonu.', '', 'Wróć do Gizzixa Grimegurgle\'a w Zębłotce na Pyłowym Bagnisku.', '', '', '', '', 0),
(11222, 'koKR', 'Dowód zdrady', 'Choć Onyxię zdemaskowano i usunięto z dworu, Nieskorni, którzy wykonali jej plan, muszą zostać ukarani. Zanieś królowi Varianowi Wrynnowi na zamek w Wichrogrodzie wieść, że to Nieskorni go porwali. Nie wątpię, że król wymierzy wszystkim zamieszanym szybką i straszliwą sprawiedliwość.$B$BMogę użyć magii, żeby przyspieszyć twoją podróż do Wichrogrodu. Po prostu porozmawiaj ze mną, kiedy będziesz $ggotów:gotowa;, $N.', 'Porozmawiaj z królem Varianem Wrynnem w Twierdzy Wichrogród.', '', '', '', '', '', '', 0),
(11223, 'koKR', 'Powrót do Jainy', 'Muszę zaplanować zniszczenie resztek Nieskornych. Przekaż, proszę, moje podziękowania lady Jainie w Theramore. Zawsze była lojalną przyjaciółką i niezłomną sojuszniczką.$B$BIdź do Dzielnicy Magów w zachodniej części miasta i porozmawiaj z arcymagiem Malinem u stóp tamtejszej wieży. Przyspieszy twój powrót do Theramore.', 'Porozmawiaj z lady Jainą Proudmoore w Theramore.', '', '', '', '', '', '', 0),
(11225, 'koKR', 'Pustelnik ze Wzgórza Czarownic', 'Bagna zdają się dziwnie działać na ludzi. Niektórzy popadają w obłęd od samego mieszkania tutaj.$B$BKażdy, kto kiedykolwiek osiadł we Dworze Bagiennego Światła, oszalał w spektakularny sposób. Ostatni właściciel, niejaki „Bagienne Oko” Jarl, już zdradza objawy.$B$BNie do końca rozumiem, co się tam dzieje; będę wdzięczny, jeśli się temu przyjrzysz.$B$BDwór stoi na wschodnim skraju bagien. Idź na wschód przez Niebieskie Mokradło i obok Wieży Północnego Cypla. Dwór leży na nawiedzonym skrawku ziemi zwanym Wzgórzem Czarownic.', 'Porozmawiaj z „Bagiennym Okiem” Jarlem we Dworze Bagiennego Światła.', '', '', '', '', '', '', 0),
(13826, 'koKR', 'Nat Pagle, wędkarz ekstremalny', '', '', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(1135, 'koKR', 'Ach, większość z nich niemal pęka od jadu, $N. Takie zbiera się zwykle tylko z młodych wiwern albo płodnych samic. Musiała tam być niezła rzeź, na tej Wysokiej Grzędzie!', 0),
(1166, 'koKR', 'Ty dobry maluch. Ja bardzo tęsknić za rzeczami. Teraz ja cię lubić.', 0),
(1168, 'koKR', 'Ty zabić dużo z armii czarnego smoka. Ty mieć dużo odwagi.$b$bTharg się cieszyć.', 0),
(1169, 'koKR', 'Zebranie tych wszystkich serc i języków było bez wątpienia niebezpiecznym przedsięwzięciem. Zgłębię teraz tajniki magii, by wyśledzić, skąd pochodzi czarna groza, która spadła na nasz dawny dom.', 0),
(1170, 'koKR', 'Czemu ty mi gadać o smokach? Ja nie lubić smoków. Ja lubić tutaj. Tu nie być smoków.', 0),
(1171, 'koKR', 'Leniwy tchórz!$b$bMok\'Morokk okazywał siłę, gdy przewodził nam Rexxar. Lecz wkrótce po odejściu Rexxara uległ pokusom władzy. Zamiast przewodzić – żądał. Nie służy swojemu ludowi, tylko oczekuje, że to my będziemy służyć jemu.$b$bTrzeba coś z tym zrobić.', 0),
(1172, 'koKR', 'Wspaniale! Minie sporo czasu, nim Onyxia zdoła złożyć kolejne jaja.$b$bDziękuję ci w imieniu mojego ludu, $N.$b$bWiele już od ciebie wymagałem. Może jednak oddasz klanowi Kamiennych Maczug ostatnią przysługę.$b$bMok\'Morokk nie nadaje się na naszego wodza. Tharg byłby znakomitym przywódcą, lecz przeszkadzają mu rany i wiek. Przepędź stąd Mok\'Morokka siłą. Dopiero wtedy będziemy mogli wybrać nowego wodza, który poprowadzi nas z powrotem do prawdziwego domu na południu.', 0),
(1173, 'koKR', 'Ta tchórzliwa kupa sadła, Mok\'Morokk, uciekła jak wystraszone dziecko. $GOddałeś:Oddałaś; nam wielką przysługę, $N.$B$BTeraz mój lud może wybrać nowego wodza – takiego, który pomoże nam raz na zawsze odzyskać dawny dom.', 0),
(1177, 'koKR', 'Ja lubić rybia głowa!$B$BJa cię teraz nie zjeść.', 0),
(1201, 'koKR', 'Dobra robota. Ich infiltratorzy są zręczni, ale nie dość, by umknąć czujnemu oku Hordy!', 0),
(1202, 'koKR', 'Należy ci się pochwała, $N. To nie była łatwa misja. Ale nasi przełożeni wysoko cenią dokumenty, które $gzdobyłeś:zdobyłaś;.', 0),
(1203, 'koKR', 'To dobre ostrze. Ma dobry zamach. To dobra kosa. Dziękuję. Dziękuję, dziękuję, dziękuję!!! Teraz chcę ją wypróbować...$B$BPóźniej. Wypróbuję ją później. Ale jak mówiłem... dzięki.', 0),
(1204, 'koKR', 'Świetnie się nadadzą! Dziękuję, $N!$B$BTeraz wypróbuję na tych językach różne techniki gotowania, żeby znaleźć najlepszy sposób na wydobycie ich smaku.$B$BW końcu stworzę danie godne podania w „Błękitnym Samotniku” w Wichrogrodzie!', 0),
(1206, 'koKR', 'Masz oczy! Masz oczy! Smaczne, smaczne pajęcze oczka!$B$BNiektóre oczy... kiedy się w nie gapisz, one gapią się na ciebie. Te zjadaj na końcu. Dotrzymują towarzystwa... tam, na bagnach.$B$BCześć, małe pajęcze oczka. Cześć! Smakujecie jak kurczak. Ciągnący się, słony kurczak!$B$BMmmm.', 0),
(1218, 'koKR', 'Ach, i o ten pieprzyk chodziło! Proszę, oto trochę dobrego bagiennego gulaszu.', 0),
(1219, 'koKR', 'Hm... Nie za dobrze czytam po orkowemu, ale to wygląda na raport... napisany przez orkowego szpiega!', 0),
(1220, 'koKR', 'Raport orkowego szpiega! Skąd to masz? Nieważne – zobaczmy, co tu jest napisane...', 0),
(1222, 'koKR', 'Pan Ignatz był tu przed chwilą z liśćmi bobrka i powiedział, że $gwyciągnąłeś:wyciągnęłaś; go z poważnych tarapatów.$B$BDziękuję, $N. Poproszę wuja, żeby ugościł cię ucztą, kiedy następnym razem odwiedzisz „Błękitnego Samotnika” w Wichrogrodzie.', 0),
(1238, 'koKR', 'Dobra robota, $N. Nasz agent, Marg Nocne Oko, stacjonował pod Theramore. Miał szpiegować miasto.$b$bTo jego najnowszy raport, a może i ostatni – z tego, co mówisz, obawiam się, że Marg zginął na bagnach...', 0),
(1239, 'koKR', 'To głowa Marga Nocnego Oka! Tak jak się obawiałem, nie żyje.$b$bSpójrz na ranę na szyi! Czy takie poszarpane cięcie mogła zadać broń, czy też naszego agenta zabiła jakaś bestia?$b$bTę zagadkę musimy rozwiązać, $N. Musimy się dowiedzieć, czy Marg zginął z rąk Przymierza!', 0),
(1251, 'koKR', 'Przyznaję, że ludzie mają dziwny gust, jeśli chodzi o ozdoby, ale czy wieszaliby nad kominkiem zwykłą żelazną tarczę? Może tę tarczę umieścili tam ci, którzy spalili karczmę.$b$bOstrzeżenie? Groźba?', 0),
(1252, 'koKR', 'Kiedy ktoś przynosi mi odznakę strażnika, nigdy nie oznacza to dobrych wieści.$b$bCzasem to mężczyzna albo kobieta, którzy polegli w walce, a mnie zostaje zanieść wieść pogrążonej w żałobie rodzinie. Kiedy indziej nigdy się nie dowiadujemy, co się z nimi stało. A jeszcze kiedy indziej bywa gorzej.', 0),
(1253, 'koKR', 'Hm, nie jestem znawcą wyrobu broni i zbroi. Ich używania – owszem, ale nie wytwarzania.$b$bTa tarcza wydaje się całkiem zwyczajna, jeśli nie liczyć uszkodzeń od ognia, który strawił karczmę.', 0),
(1258, 'koKR', 'To wspaniałe okazy, $N! Skorupy są w idealnym stanie, a mięso różowe i delikatne. W twoich żyłach płynie krew kucharza, jestem tego pewien!', 0),
(1259, 'koKR', 'Witaj, $N. Chcesz informacji o konkretnym członku straży Theramore? Reethe, tak?$b$bDaj mi chwilę, znajdę właściwą księgę.', 0),
(1268, 'koKR', 'Ślady kopyt... To mogły być kolcozwierze, jak sądzę. A może nawet centaury. Na Pustkowiach jest ich niemało i nie zdziwiłbym się, gdyby dopuściły się czegoś takiego.$b$bMówiłem ci? Nie chodzi tylko o to, że karczma spłonęła... Zginęły kobieta i szczenię właściciela. Paskudna sprawa.$b$bTak czy inaczej, wyślę Kagoro, by ustalić, dokąd prowadzą tropy.', 0),
(1269, 'koKR', 'Znam tego człowieka, Pavala Reethe\'a. Żałosny, nawet jak na swój gatunek. Zdezerterował, porzucając towarzyszy broni, i teraz ukrywa się w lasach.$b$bWysłałem Ogrona, żeby go wytropił. Niektórzy podejrzewają, że podkrada nasze zapasy. Zdaje się, że widziałem, jak Ogron ruszał na południowy wschód.', 0),
(1273, 'koKR', 'Hmf. Dobrze, że Reethe nie będzie już czaił się po bagnach, ale szkoda, że ludzie są tak wątli, iż nie wylizał się z drobnej rany od strzały.$b$bWygląda na to, że ten wątek zagadki prowadzi donikąd i musimy szukać gdzie indziej.', 0),
(1282, 'koKR', 'Naprawdę nazywa się James Hyal. Otworzył karczmę na skraju Pustkowi. Chciał stworzyć miłe miejsce na postój dla podróżnych...$B$BMoże za wysoko mierzył, ale przez jakiś czas karczma dobrze prosperowała. Potem straciliśmy kontrolę nad drogami na bagnach i przejęły je ogry.$B$BJames był zbyt uparty, żeby dla bezpieczeństwa za naszymi murami porzucić swoje marzenie, i karczma „Cienisty Wypoczynek” spłonęła doszczętnie. Prowadzimy śledztwo, ale bez większych sukcesów. Jeśli chcesz pomóc, zobacz, co uda ci się znaleźć w zgliszczach.', 0),
(1284, 'koKR', 'Ślady kopyt, co? To prawda, że na ziemiach w pobliżu Pyłowego Bagniska centaury są wyjątkowo aktywne. Podczas krótkich wypadów na Pustkowia natknęliśmy się na ich obozy i siedziby rozsiane po całej okolicy.$b$bWyślę Falgrana Hastila, jednego z naszych tropicieli, żeby sprawdził, dokąd prowadzą ślady.', 0),
(1285, 'koKR', 'Zaginiony? To uprzejmy sposób Tesorana na powiedzenie „zdrajca”.$b$bBez wątpienia to jeden z tych głupców tak ślepo oddanych admirałowi Daelinowi, że aż stali się zdrajcami. Czyż to nie wyborna ironia? Dezerterzy oskarżają nas o zdradę Przymierza.', 0),
(1286, 'koKR', 'Vimes cię przysłał? Nie mógł sam odwalić brudnej roboty, co...', 0),
(1287, 'koKR', 'Wyślę porucznika Caldwella, żeby rozprawił się z dezerterami na Straconym Cyplu. Polecę mu też odnaleźć Reethe\'a. Bagna nie są aż tak wielkie i bezdrożne, żeby nie mógł go znaleźć.', 0),
(1319, 'koKR', 'Hm... ciekawy kawałek żelaza. Na pewno nie wykuł go żaden z kowali, których znam po tej stronie morza, i z pewnością nie jest to moja robota.', 0),
(1320, 'koKR', 'Niewiele z tego wynika, ale musimy o tym pamiętać. Oby inne elementy tej zagadki wskoczyły na swoje miejsce i dały pełniejszy obraz tego, co się stało.', 0),
(1321, 'koKR', 'To dobra tarcza. Bardzo mocna, ciężka, dobra. Ale Do\'gol jej nie potrzebować. Ja robić tarcze, nie kupować, $N.$b$bTrzeba to wiedzieć.', 0),
(1322, 'koKR', 'Nie lubię pająków tak dużych, że nie mogę na nich usiąść i ich rozgnieść.$b$bDzięki, że je $gprzyniosłeś:przyniosłaś;, $N. Teraz je rozerwę i wyleję na tarczę...', 0),
(1323, 'koKR', 'Mosarn? Brzmi znajomo... Ale nie mogę skojarzyć. Może później sobie przypomnę.$b$bPewnie to nic ważnego. Tarcza może pochodzić skądkolwiek i nic nie znaczyć...', 0),
(1390, 'koKR', 'Dzięki za wykonaną robotę!', 0),
(1948, 'koKR', 'Aha! Masz nefryt i $gzrobiłeś:zrobiłaś; jeżynę! Świetnie!$B$BCzy to dym unosi ci się z uszu? Może $gstałeś:stałaś; za blisko, kiedy piorun uderzył w totemowe patyki, ale nie martw się. Trafienie piorunem przynosi szczęście!', 0),
(1952, 'koKR', 'Oto różdżki, które zrobiłam. Wybierz sobie!', 0),
(1954, 'koKR', 'Och, jaka miła! Nie, nie mam na myśli, że jest „miła” tak, jak miły jest chłodny sok w upalny dzień.$B$BWłaściwie, jak się nad tym zastanowić, to wcale NIE jest miła. Nie sok. Kula!$B$BSkup się, $N! Musisz być $gskupiony:skupiona;, jeśli mamy kiedykolwiek skończyć nasze zadanie!', 0),
(1955, 'koKR', 'Świetna robota, $N! $GDałeś:Dałaś; temu demonowi nauczkę, której prędko nie zapomni.$B$BDwa razy się zastanowi, zanim znów wychyli swój paskudny łeb w tym świecie, szukając $ggłupiego śmiertelnika, który go pokonał:głupiej śmiertelniczki, która go pokonała;. Pewnie tym razem z przyjaciółmi. Wielkimi, łuskowatymi przyjaciółmi, którzy niczego bardziej nie pragną, niż rozszarpać cię na drobne kawałeczki.$B$BChyba cię nie przestraszyłam... $N?', 0),
(1956, 'koKR', 'Udało ci się? Świetnie!$B$BRozmawiałam z kilkorgiem kolegów po fachu i kiedy padło twoje imię, powiedzieli: „Wiesz, $N naprawdę dobrze radzi sobie pod presją!”$B$BAle kiedy im powiedziałam, że wysłałam cię do Uldamanu na obsydianowego strażnika, stwierdzili, że zwariowałam! Powiedzieli: „Tabetho, zwariowałaś! $N nie ma szans z tym strażnikiem!”$B$BA ja na to: „Zobaczymy”, a oni: „No, zobaczymy...”$B$BNo i pokazaliśmy im, prawda?', 0),
(1957, 'koKR', 'Udało ci się! Ani przez sekundę w ciebie nie wątpiłam! No dobra, może przez sekundę, dwie... ale w zasadzie nie miałam wielu wątpliwości.$B$BSłowo.', 0),
(1958, 'koKR', 'Możesz być z siebie $gdumny:dumna;, $N. Wielu magów poległo w starciu ze stworzeniami, którym $gstawiłeś:stawiłaś; czoła.$B$BNiebiańska kula jest gotowa. A jeśli wolisz, mogę osadzić ją na kosturze. Wybór należy do ciebie. Ja wolałabym kulę, ale kim jestem, żeby oceniać?', 0),
(2846, 'koKR', 'Wspaniale! $GZnalazłeś:Znalazłaś; ją! I co równie ważne – Velratha już jej nie ma! Dziękuję, $N. Mam u ciebie dozgonny dług!$B$BA jeśli wcześniej byłam trochę... wredna, nie przejmuj się tym. Przekonasz się, że dla tych, którzy mnie nie okradli, jestem o wiele milsza.', 0),
(4961, 'koKR', 'Świetna robota, $N! $GDałeś:Dałaś; temu demonowi nauczkę, której prędko nie zapomni. $GWykazałeś:Wykazałaś; się wielką mocą i umiejętnościami. Chyba czas, żebyś $gwrócił:wróciła; do Menary z oczyszczoną kulą i $gzrobił:zrobiła; z niej dobry użytek.$B$BPowodzenia. Może nasze ścieżki jeszcze się skrzyżują.', 0),
(6570, 'koKR', 'Czyżby tak brakowało zdolnych żołnierzy, że Nefarian przysyła mi pisklęta? Nigdy nie przejdziesz moich prób, smoczątko.', 0),
(6582, 'koKR', 'Jedna z kilku prób zaliczona... sss...', 0),
(6583, 'koKR', 'Kolejna zaliczona...', 0),
(6584, 'koKR', 'Zossstała próba najbardziej znienawidzonych...', 0),
(6585, 'koKR', 'Twoje oddanie budziło moje wątpliwości, pisklę. Wytrwałość pozwoliła ci jednak zdominować naszych wrogów i przynieść chwałę naszemu stadu.$B$BMuszę teraz przygotować czaszki do twojego wyniesienia.', 0),
(6607, 'koKR', 'To ci dopiero połów!$B$BChodź tu, pokażę ci, jak zarzucić parę linek.', 0),
(6624, 'koKR', 'Witaj w Oddziale Urazowym Przymierza, $gdoktorze:pani doktor; $N.', 0),
(7070, 'koKR', 'Są idealne, $N. Właściwie inni poszukiwacze przygód też już stamtąd wrócili i z tego, co przynieśli, zdołałem wykonać te oto... proszę, weź jeden w nagrodę za swój trud. I jeszcze raz dziękuję za kolejne próbki do badań.', 0),
(8970, 'koKR', 'Szczerze mówiąc, $N, dziwię się, że $gwróciłeś:wróciłaś; w jednym kawałku. Z drugiej strony Wyspa Alcaz to pewnie teraz najmniejsze z twoich zmartwień.$B$BDobra, daj mi chwilę... wróżenie to nie coś, gdzie wystarczy pstryknąć palcami i czekać na trafne odpowiedzi.', 0),
(9437, 'koKR', 'Dobra robota, $N! Gdy tylko Ithania odpocznie, a ja zakończę przygotowania, opuścimy to przemoknięte pustkowie i wrócimy do cywilizacji.', 0),
(11123, 'koKR', 'Dobrze widzieć, że kapitan Vimes w końcu przydziela do tego śledztwa kogoś jeszcze.$B$BPosypałem teren proszkiem odblaskowym. Ujawni podejrzane przedmioty i ślady, co pomoże ci skupić się na tym, co ważne. Obejrzyj wszystko, co proszek podświetli.', 0),
(11124, 'koKR', '<Inspektor przygląda ci się z czymś, co może być tylko nieufnością.>$B$BPowiedziano mi, że masz... pomagać w tym śledztwie. No dobrze.$B$BUżywam tego proszku, by szukać w ruinach śladów, które mogłyby pomóc zidentyfikować napastników. Podświetli wszystko, co mogło mieć związek z atakiem. Śmiało oglądaj wszystko, co wygląda podejrzanie.', 0),
(11126, 'koKR', 'Dobra robota, $N. Chyba udało nam się ich zaskoczyć. Ich agenci pewnie myśleli, że w murach miasta są bezpieczni.$B$BZ czasem agitatorzy wrócą i znów zaczną szerzyć kłamstwa. Wykorzystamy czas, który nam $gzyskałeś:zyskałaś;, żeby jeszcze szczelniej odciąć dezerterów.', 0),
(11128, 'koKR', '<Agentka WW:7 kiwa głową z aprobatą.>$B$BDoskonale. Pozostało już tylko ośmieszyć dezerterów, żeby nigdy więcej nie zdobyli przyczółka w Theramore, a ja mam na to idealny plan.', 0),
(11133, 'koKR', '<Calia chichocze, gdy opisujesz reakcje strażników na propagandę.>$B$BTak jak liczyłam! Śmiało można powiedzieć, że każdy agent dezerterów, który spróbuje przeniknąć do Theramore, zostanie wyśmiany i przegoniony z miasta!', 0),
(11134, 'koKR', 'Prośba Gavisa nie jest tak dziwaczna, jak może się wydawać. Przy odpowiednim podejściu lady Jaina może przyjąć dezerterów z powrotem, ale to oczywiście jej decyzja.$B$BWspółpraca z tobą to była przyjemność, $N. Bez twojej pomocy operacja raczej nie poszłaby tak gładko. Kiedy złożę raport w Wichrogrodzie, wymienię cię w nim jako osobę, która położyła kres zagrożeniu ze strony dezerterów.', 0),
(11136, 'koKR', '<Kapitan nawet nie kryje, że ocenia twoje umiejętności.>$B$BWięc $gsłyszałeś:słyszałaś; o niedawnym rozbiciu statku u wybrzeży? Dobrze, przyda mi się pomoc w potwierdzeniu moich podejrzeń co do rozbitków. Witaj na pokładzie, $N.', 0),
(11137, 'koKR', '<Kapitan Wymor bierze od ciebie rozkazy i je przegląda.>$B$BCo, u licha, może oznaczać „cenny ładunek”? Nieskorni zajmowali się drobnym przemytem na ziemiach Wichrogrodu, ale to chyba przerasta ich możliwości. Język tych rozkazów wskazuje na bogatego albo szlachetnie urodzonego mecenasa.', 0),
(11138, 'koKR', '<Renn przegląda rozkazy.>$B$BWięc na pokładzie był cenny ładunek! Musimy go znaleźć, zanim Nieskorni go odzyskają. Ci goście nie są nurkami, ale jeśli masz mi pomóc znaleźć ładunek, będziemy potrzebowali trochę ich sprzętu.', 0),
(11139, 'koKR', 'Rany, jest w gorszym stanie, niż myślałem, a te narzędzia...$B$BNo cóż, obiecałem, że doprowadzę go dla ciebie do porządku, więc lepiej wezmę się do roboty.', 0),
(11140, 'koKR', '<Renn przetrząsa zawartość kasetek, które udało ci się wyłowić.>$B$BDobra robota. A teraz zobaczmy, czy jest tu nasz „cenny ładunek”...', 0),
(11141, 'koKR', 'Ty i Renn wykonaliście świetną robotę, wydobywając te informacje na światło dzienne i od razu je zgłaszając. Teraz musimy potwierdzić wasze odkrycia. Gdyby okazały się błędne, skutki byłyby zbyt poważne.', 0),
(11142, 'koKR', '<Lady Jaina uważnie słucha twojego raportu z rozpoznania z powietrza.>$B$BKrąg runiczny, drakanie? Nieskorni sprzymierzyli się z NIĄ? Z tą zdrajczynią?$B$B<Lady Jaina opanowuje się i przygotowuje do wyjaśnień.>', 0),
(11143, 'koKR', 'Kapitan Vimes uważa, że za zniszczeniem karczmy „Cienisty Wypoczynek” stoją Ponure Totemy? Nie byłyby pierwsze na mojej liście podejrzanych, ale skoro kapitan Vimes przysłał cię tu, żebyś $gsprawdził:sprawdziła; ten trop, musi mieć swoje powody. Tak czy inaczej, Ponure Totemy od dawna są nam solą w oku, więc każda dodatkowa pomoc jest mile widziana.', 0),
(11144, 'koKR', '<Kapitan Darill zerka na plan bitwy.>$B$BJaśniej już być nie może. Postanowili na własną rękę uderzyć na ludzkie osady w okolicy i nie mam wątpliwości, że Theramore jest następne na ich liście.', 0),
(11145, 'koKR', 'Uwolnieni jeńcy już wracają z Wioski Czarnego Kopyta. Informacje, które kapitan od nich dostaje, dadzą nam przewagę w następnej bitwie z Ponurymi Totemami.$B$BMasz moją wdzięczność i wdzięczność moich ludzi.', 0),
(11146, 'koKR', 'Trochę cię podrapały, ale to nic poważnego. Na pewno jesteś w dużo lepszym stanie, niż będą Ponure Totemy, kiedy nasi nowi przyjaciele, raptory, się z nimi rozprawią.', 0),
(11147, 'koKR', '<Sierżant nawet nie próbuje ukryć uśmiechu.>$B$BDobrze. To powinno zapobiec najazdowi czy dwóm.', 0),
(11148, 'koKR', '<Kapitan Darill ogląda uzbrojenie, które $gprzyniosłeś:przyniosłaś; z Wioski Czarnego Kopyta.>$B$BNie ma wątpliwości. Pasuje dokładnie do opisu, jest tylko jeden problem – nigdy nie użyto go w bitwie. Wioska Czarnego Kopyta nie może być jedyną placówką Ponurych Totemów na bagnach.', 0),
(11149, 'koKR', 'Więc chcesz, żebym wywróżyła, gdzie są Ponure Totemy, co? A co powiesz, kiedy ci odpowiem, że nie ma takiej potrzeby?', 0),
(11150, 'koKR', 'Mam nadzieję, że Ponure Totemy zrozumiały wiadomość. Każda próba powrotu spotka się z czymś znacznie gorszym niż zwykła pochodnia. Już ja i moi uczniowie o to zadbamy.', 0),
(11151, 'koKR', '<Kapitan uważnie słucha twojego raportu.>$B$BPomściliśmy Jamesa i jego rodzinę, ale nawet to nie przywróci tego, co zostało zniszczone.', 0),
(11152, 'koKR', '<Kapitan Vimes uśmiecha się lekko, gdy opowiadasz, czego $gbyłeś:byłaś; świadkiem przy grobie rodziny Hyal.>$B$BDobrze wiedzieć, że rozumieją. Nie $gpowiedziałeś:powiedziałaś; im o Jamesie, prawda?$B$BPrzekażę mu wiadomość od żony, ale wątpię, żeby zrozumiał.', 0),
(11156, 'koKR', '<Uczeń Morlann kiwa głową.>$B$BDobrze. Nie powiem, żebym miał tęsknić za takim towarzystwem, o ile można to tak nazwać. Człowiek by pomyślał, że przynajmniej w środku bagna zazna trochę spokoju, nie?', 0),
(11158, 'koKR', '<Brogg przyjmuje pióra.>$B$BBrogg zadowolony z tych piór. Bardzo silna magia. Brogg nie wiedzieć, co raptory robić, że pióra mieć moc, ale pióra raptorów zawsze najlepsze do rytuału.', 0),
(11159, 'koKR', 'Brogg dziękuje ci za pomoc, choć wie, że nadrządca Mok\'Morokk nigdy tego nie zrobi. Przynajmniej ocaleni z Kamiennych Maczug mogą w końcu zająć się kłopotami z żywymi, a zmarłych zostawić tam, gdzie ich miejsce. Brogg musi zrobić już tylko jedną rzecz.', 0),
(11160, 'koKR', 'Brogg ci dziękuje, $N. Brogg ma wielkie plany wobec sztandaru klanu.', 0),
(11161, 'koKR', 'Brogg ci dziękuje, $N. Kiedy Brogg doda ich magię do totemu, totem będzie mógł wyzwolić duchy poległych przyjaciół Brogga.', 0),
(11162, 'koKR', '<Brogg słucha, jak opowiadasz o tym, co się stało przy wejściu do Leża Onyxii.>$B$BBrogg podejrzewał, że Onyxia stchórzy i nie stanie z tobą do walki. Całe Czarne Stado takie – atakuje tylko wtedy, gdy zwycięstwo pewne.$B$BBrogg jest wdzięczny za twoją pomoc, $N, i nigdy nie zapomni, co dla niego $gzrobiłeś:zrobiłaś;. Brogg nigdy nie przestanie walczyć o to, żeby Kamienne Maczugi wróciły tam, gdzie ich miejsce.', 0),
(11169, 'koKR', '<Uczeń słucha, jak opisujesz swój eksperyment.>$B$BMgiełka i trochę błyskawic? To wszystko? Ten totem musi potrafić coś więcej! Ponure Totemy nie przynosiłyby czegoś takiego na pole bitwy, gdyby nie miało to jakiegoś zastosowania.', 0),
(11172, 'koKR', 'Więc przysłali cię ci magowie pustelnicy? Skąd mam wiedzieć, że mogę ci zaufać?$B$BW sumie przyda mi się pomoc. I tak nie ma tu niczego, co mogłoby zainteresować maga.', 0),
(11173, 'koKR', '<Uczeń Garion ogląda jad.>$B$BIdealnie! Nigdy nie pozna różnicy.', 0),
(11174, 'koKR', 'No, rzeczywiście jest tam trochę czyściej...$B$BChyba czas zabrać się do ratowania tego, co zostało z wraku.', 0),
(11177, 'koKR', 'Zjeżdżaj z mojego trawnika... chyba że chcesz pomóc staremu „Bagiennemu Oku” w małym gotowaniu. Co ty na to?', 0),
(11180, 'koKR', '<Mordant wyjmuje małą kartkę i pióro, po czym zaczyna notować twoje odkrycia.>$B$BZ tego, co $gustaliłeś:ustaliłaś;, wynika, że tutejsze duchy to wszyscy, którzy kiedykolwiek żyli na tej ziemi, nie tylko poprzedni mieszkańcy.$B$BCoś ich deprawowało i zabijało. Ci, którzy przychodzą po nich, poznają prawdę, gdy jest już za późno. Musimy z tym skończyć, $N!', 0),
(11181, 'koKR', '<Mordant bierze od ciebie pęk ziół.>$B$BPasują dokładnie do opisu! Przygotowałem pochodnię, kiedy cię nie było. Zostało już tylko przymocować zioła tu, na końcu.', 0),
(11183, 'koKR', 'Zadziałało?$B$B<Mordant odchrząkuje.>$B$BTo znaczy... zadziałało! Jarl i ja mamy u ciebie dług, $N. Teraz jedynym problemem pozostaje gust mojego przyjaciela w kwestii mebli, a obawiam się, że tego nie da się tak łatwo rozwiązać.', 0),
(11184, 'koKR', 'Dzięki niebiosom, ktoś w końcu skorzystał z tej oferty. Już myślałem, że będę musiał potroić nagrodę, żeby ktoś zabił tego głupiego raptora, a na to nie byłoby nas stać!', 0),
(11185, 'koKR', '<Andello czyta list, wstrząśnięty jego treścią.>$B$BOd dawna mieliśmy wątpliwości co do współpracy Hordy z Porzuconymi, a to tylko potwierdza nasze podejrzenia. Ze wsparciem magii i broni Porzuconych Ponure Totemy stałyby się jeszcze groźniejszym wrogiem. Układ sił w Kalimdorze mógłby się znacznie zmienić.', 0),
(11186, 'koKR', 'Jeśli to jest tym, na co wygląda, Porzuceni będą musieli się gęsto tłumaczyć!$B$BWybryki Ponurych Totemów od dawna wystawiają cierpliwość wodza na próbę. Dotąd traktowaliśmy to jako sprawę, którą taureni powinni załatwić między sobą, ale ten list może to zmienić.$B$BZbadanie tych podejrzeń zajmie trochę czasu, ale nie mów nikomu o tym, co dziś $gwidziałeś:widziałaś;.', 0),
(11191, 'koKR', 'Dobrze. Przyda mi się każda pomoc, jaką możesz zaoferować. Najważniejsze to znowu zapalić lampę.', 0),
(11192, 'koKR', 'Cóż, mam wątpliwości, ale to na razie jedyne dostępne rozwiązanie. Kiedy już ją uruchomimy, na pewno znajdzie się czas, żeby poszukać innych sposobów zasilania lampy.', 0),
(11193, 'koKR', 'No proszę, jak to miło ze strony Babs, że to przysłała. Nie wiem, czy $gprzekartkowałeś:przekartkowałaś; tę książkę, ale w tych opowieściach jest sporo prawdy. Żeglarze nie wymyślili tego wszystkiego, wiesz.', 0),
(11194, 'koKR', 'Więc chcesz się dowiedzieć czegoś o potworach morskich? Hmm... no dobrze, zawrę z tobą umowę, ale będzie w to zamieszane sporo alkoholu i trochę wstydu z twojej strony.', 0),
(11198, 'koKR', 'Dobra robota, $N! Przyznaję, kiedy pierwszy raz zobaczyłem tę bestię, wątpiłem, czy zdołamy obronić doki, ale znakomicie $gpokierowałeś:pokierowałaś; obrońcami!', 0),
(11200, 'koKR', '<Krog ogląda broń i zbroje, które $gprzyniosłeś:przyniosłaś; z Wioski Czarnego Kopyta.>$B$BTo bez wątpienia robota Mosarna. Dalsze wypytywanie go mogłoby zwrócić zbyt wiele uwagi, ale wobec Ponurych Totemów mamy nieco większą swobodę działania.', 0),
(11201, 'koKR', '<Krog czyta plan bitwy.>$B$BNie mam wątpliwości, że Ponure Totemy występują przeciwko ludziom. Nie rozumiem tylko, jakie mają zamiary wobec nas. Poczynania Ponurych Totemów już wcześniej wywoływały napięcia w Hordzie, ale wódz zawsze je rozładowywał.', 0),
(11203, 'koKR', '<Tabetha lekko się uśmiecha.>$B$BKrog chce, żebym wypatrzyła Ponure Totemy w wizji, co? Cóż, w tym wypadku magia nie jest mi potrzebna.$B$BWygląda na to, że mamy wspólnego wroga. Ponure Totemy zbudowały w pobliżu placówkę i są nieustannym utrapieniem dla mnie i moich uczniów.', 0),
(11205, 'koKR', 'Ponure Totemy nie powinny mieć kłopotu ze zrozumieniem naszej najnowszej wiadomości.$B$BCo do ciebie, twój łącznik w Paprotni zechce się dowiedzieć o twoim sukcesie. Wiem, że zniszczenie karczmy „Cienisty Wypoczynek” mogłoby stać się źródłem napięć między Hordą a Przymierzem. Jeśli spotkam jakichś śledczych z Theramore, chętnie im powiem, że Ponure Totemy działały na własną rękę.', 0),
(11206, 'koKR', '<Krog słucha twojego raportu.>$B$BJestem pod wrażeniem, $N. Sądziłem, że zbrodniarzy z Ponurego Totemu będzie trudniej odnaleźć.$B$BOstrzeżenia Tabethy nie trafiły w próżnię, ale nie mnie karcić Ponure Totemy. Oczywiście wspomnę o tym w raporcie dla wodza. Nie mów o tym nikomu, dopóki Thrall nie rozprawi się z Ponurymi Totemami. Dobrze się $gspisałeś:spisałaś;, rozwiązując zagadkę „Cienistego Wypoczynku” i oszczędzając nam podejrzeń Theramore.', 0),
(11207, 'koKR', 'Rany! $GZnalazłeś:Znalazłaś; o wiele więcej, niż się spodziewałam. Nie wiem, ile Drazzit spodziewał się tu znaleźć, ale na razie musi mu to wystarczyć.', 0),
(11208, 'koKR', '<Drazzit przyjmuje od ciebie ładunek.>$B$BJestem tak głodny, że zjadłbym smoka! Dzięki niebiosom, Moxie w końcu przysłała tu trochę tego ładunku. Doszło do tego, że gramy w kości z ogrem o to, co uda mu się upolować na łowach!', 0),
(11209, 'koKR', 'Wcale nieźle, ale wiesz co? Na twoim miejscu jak najszybciej bym się wykąpał.$B$BA teraz co do twojego potwora morskiego...$B$BTymczasem częstuj się piwem czy dwoma.', 0),
(11210, 'koKR', '<Opowiadasz o przygodach z Natem Pagle\'em, starannie pomijając część o „teście przynęty”.>$B$BCóż, wygląda na to, że czeka nas sporo pracy. Zajmę się przygotowaniami.', 0),
(11211, 'koKR', 'Miło ze strony Tabethy, że cię tu przysłała. Poprosiłbym ją o trochę jedzenia, dopóki nie uporamy się z wrakiem sterowca, ale wiem, że teraz nie ma nic na zbyciu. Jeśli masz ochotę na przygodę, wyznaczyłem nagrodę za zabicie wyjątkowo paskudnego raptora.', 0),
(11212, 'koKR', 'Miło, że Theramore kogoś przysłało. Podejrzenia twojego przyjaciela strażnika były słuszne. Mamy nowych sąsiadów, i to nie takich, do których idzie się z ciastem na powitanie.', 0),
(11213, 'koKR', 'Całe szczęście, że Nazeer pomyślał, żeby kogoś przysłać. Mamy nowych sąsiadów i odkąd rozbili obóz, są tylko utrapieniem.', 0),
(11214, 'koKR', 'Więc Theramore chce robić interesy? Takiej oferty nie odrzucę. Zapasów mamy teraz jak na lekarstwo, więc przyda nam się każdy kontakt handlowy!', 0),
(11215, 'koKR', 'Nie odmówię żadnej pomocy! Właśnie się tu urządzamy i próbujemy jak najlepiej wykorzystać to, co mamy, dopóki nie dotrą zapasy ze sterowca.', 0),
(11217, 'koKR', 'Dziękuję! Dzięki temu nasi ludzie w terenie wytrzymają, dopóki Moxie nie wróci z resztą zapasów z wraku sterowca.', 0),
(11222, 'koKR', '<Najwyższy lord Bolvar słucha, jak przekazujesz wiadomość od Jainy.>$B$BJesteś tego $gpewien:pewna;? To bardzo poważne oskarżenie...', 0),
(11223, 'koKR', 'To wspaniałe wieści, $N! Martwiłam się, że najwyższy lord może zakwestionować prawdziwość naszych informacji, ale teraz widzę, że moje obawy były bezpodstawne.$B$BZostaniesz sowicie $gnagrodzony:nagrodzona; za swoje wysiłki na rzecz Theramore i Przymierza.', 0),
(11225, 'koKR', 'Przychodzisz mnie szpiegować? Nie?$B$BTo może doceniasz wykwintną kuchnię? Dobrze, możesz pomóc!', 0),
(11744, 'koKR', 'Zbezcześć wielkie ognisko Przymierza na Pyłowym Bagnisku!', 0),
(11771, 'koKR', 'Zbezcześć wielkie ognisko Hordy na Pyłowym Bagnisku!', 0),
(11815, 'koKR', 'Uczcij płomień Pyłowego Bagniska!', 0),
(11847, 'koKR', 'Uczcij płomień Pyłowego Bagniska!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(1135, 'koKR', '$GZnalazłeś:Znalazłaś; Wysoką Grzędę, $N? Poszczęściło ci się z tamtejszymi wiwernami?', 0),
(1166, 'koKR', 'Ja spragniony grogu. Ja tęsknić też za tabaką. Gdzie kasetka? Ty iść i przynieść nadrządcy Mok\'Morokkowi.$b$bSzukać na południu, w starym domu. Ja za bardzo zajęty rządzeniem ogrami, żeby iść.', 0),
(1168, 'koKR', 'Mok\'Morokk kazać wszystkim ogrom zostać i pilnować tego miejsca. Ja myśleć, że ogry muszą zabić armię czarnego smoka i odzyskać stary dom.$b$bTy pomóc ogrom odzyskać dom. Pomóc ogrom się zemścić.', 0),
(1169, 'koKR', 'Dzięki sercom i językom osmalonego potomstwa armii czarnego smoka zdołam ustalić, która nikczemna bestia sprowadziła swój pomiot do naszego domu. Być może, wiedząc więcej o napastnikach, zdołamy zniszczyć ich raz na zawsze i podźwignąć Wioskę Kamiennych Maczug z ruin.$b$bRzecz jasna, przekonanie Mok\'Morokka, by ruszył swoje ospałe, tłuste cielsko z tej błotnistej dziury, samo w sobie będzie zadaniem na miarę eposu...', 0),
(1172, 'koKR', 'Musisz śpieszyć do Smoczego Mroku, $n. Jaja Onyxii leżą na całym Żmijowym Trzęsawisku i jeśli szybko czegoś nie zrobimy, staniemy wobec przytłaczającej przewagi liczebnej.$b$bZniszcz jej jaja! Nie pozwól, by plaga czarnych smoków rozlała się po naszej ojczyźnie!', 0),
(1173, 'koKR', 'Sądziłem, że spróbujesz przepędzić Mok\'Morokka z wioski. A ty przychodzisz do mnie na pogawędkę?', 0),
(1177, 'koKR', 'Dawać jedzenie albo ja cię zjeść.', 0),
(1201, 'koKR', '$GZnalazłeś:Znalazłaś; infiltratorów, $N?', 0),
(1202, 'koKR', '$GZnalazłeś:Znalazłaś; dokumenty, $N? Zawierają informacje kluczowe dla stabilności Przymierza, a tym samym kluczowe dla bezpieczeństwa Hordy.', 0),
(1203, 'koKR', 'Masz moje ostrze??', 0),
(1204, 'koKR', 'Masz te rozwidlone języki?', 0),
(1206, 'koKR', 'Gdzie są te oczy?', 0),
(1218, 'koKR', 'Pieprzyk. Każdemu przyda się trochę pieprzu w życiu. Zgadzasz się?', 0),
(1219, 'koKR', 'Masz coś do zameldowania?', 0),
(1222, 'koKR', '$GWidziałeś:Widziałaś; pana Ignatza? Jakiś czas temu wysłałem go na bagna i jeszcze nie wrócił!', 0),
(1239, 'koKR', 'Masz do zgłoszenia jeszcze jedną sprawę, $N?', 0),
(1251, 'koKR', 'Co tam masz, $n? Dowód ze zgliszcz karczmy „Cienisty Wypoczynek”?', 0),
(1252, 'koKR', '$GZnalazłeś:Znalazłaś; coś ciekawego w karczmie „Cienisty Wypoczynek”?', 0),
(1253, 'koKR', '$GZnalazłeś:Znalazłaś; jakieś dowody na miejscu karczmy „Cienisty Wypoczynek”?', 0),
(1258, 'koKR', 'Moje badania nad językami błotnoskalnych żółwi idą świetnie. Mam nadzieję, że polowanie na kraby też ci się udaje?', 0),
(1269, 'koKR', '$GZnalazłeś:Znalazłaś; jakieś tropy w sprawie tego, co stało się w karczmie „Cienisty Wypoczynek”?', 0),
(1273, 'koKR', '$GZnalazłeś:Znalazłaś; Reethe\'a?', 0),
(1319, 'koKR', 'Masz coś, na co mam rzucić okiem?', 0),
(1321, 'koKR', 'Coś dla mnie, $N?', 0),
(1322, 'koKR', 'Masz te gruczoły od pająków?', 0),
(1948, 'koKR', 'Witaj, $N. Masz przedmioty, których potrzebuję?', 0),
(1954, 'koKR', 'Masz piekielną kulę, $N?', 0),
(1955, 'koKR', 'Musisz zabić tego demona, żeby usunąć z kuli jego skazę, $N.', 0),
(1956, 'koKR', '$GByłeś:Byłaś; w Uldamanie, $N? $GPokonałeś:Pokonałaś; obsydianowego strażnika?', 0),
(1957, 'koKR', 'Nie $gzabiłeś:zabiłaś; wymaganej liczby przypływów many, $N.', 0),
(2846, 'koKR', 'Masz tiarę, $N? Czy Velratha przekonała się już, ile kosztuje zadzieranie ze mną?', 0),
(4961, 'koKR', 'Musisz zabić tego demona, żeby na zawsze usunąć jego obecność z kuli, $N.', 0),
(6582, 'koKR', '<Emberstrife syczy.>', 0),
(6583, 'koKR', 'Nie wracaj tu, dopóki nie wykąpiesz się we krwi naszych wrogów i nie opijesz się ich cierpieniem.', 0),
(6584, 'koKR', 'Jak na ironię, pisklę, czasss nagli.', 0),
(6585, 'koKR', 'Zmiany... sss... Wyczuwam, jak w tobie zachodzą, pisklę. Przejdź tę próbę, a zossstanie już tylko ceremonia.', 0),
(6607, 'koKR', 'Coś dziś bierze?', 0),
(7070, 'koKR', '$GWybrałeś:Wybrałaś; się już tam? Wiem, że to bardzo niebezpieczne, ale jeśli ci się uda, będzie naprawdę warto.', 0),
(8970, 'koKR', 'Krwawy wodorost, $N, cała sterta – tego potrzebuję do zasilenia moich zaklęć wróżbiarskich. Pewnie trzeba będzie zabrać ze sobą na Wyspę Alcaz co najmniej paru przyjaciół, żeby go zebrać... te Strashaz to paskudna banda!', 0),
(9437, 'koKR', 'Czy Ithania jest już wolna, a mój ładunek odebrany tym kaprom udającym wojsko?', 0),
(11126, 'koKR', '$GWygnałeś:Wygnałaś; agentów dezerterów z Theramore?', 0),
(11128, 'koKR', 'Udało ci się znaleźć i przejąć pozostałe ulotki propagandowe?', 0),
(11133, 'koKR', 'Zdawało mi się, że słyszę śmiech z koszar. $GRozdałeś:Rozdałaś; ulotki, które ci dałam?', 0),
(11134, 'koKR', '$GZakończyłeś:Zakończyłaś; szturm na bazę dezerterów?', 0),
(11137, 'koKR', 'Udało ci się wytropić ich przywódcę?', 0),
(11138, 'koKR', 'Witaj, $N. Co cię tu sprowadza?', 0),
(11139, 'koKR', 'Zobaczmy, co udało ci się „pożyczyć” od Nieskornych.', 0),
(11140, 'koKR', 'Czy przeszukanie wraku ujawniło coś w sprawie ładunku Nieskornych?', 0),
(11144, 'koKR', 'Udało ci się znaleźć jakiś ślad rozkazów?', 0),
(11145, 'koKR', 'Udało ci się uwolnić jeńców z Wioski Czarnego Kopyta?', 0),
(11146, 'koKR', '$GSchwytałeś:Schwytałaś; te raptory?', 0),
(11147, 'koKR', '$GWypuściłeś:Wypuściłaś; raptory w Wiosce Czarnego Kopyta?', 0),
(11148, 'koKR', '$GZdobyłeś:Zdobyłaś; tę broń z Wioski Czarnego Kopyta?', 0),
(11150, 'koKR', '$GZrobiłeś:Zrobiłaś; dobry użytek z tej pochodni?', 0),
(11152, 'koKR', '$GZłożyłeś:Złożyłaś; wieniec?', 0),
(11156, 'koKR', 'Udało ci się coś zdziałać, żeby powstrzymać ataki Ponurych Totemów?', 0),
(11158, 'koKR', '<Brogg patrzy na ciebie z nadzieją.>$B$BTy przynieść Broggowi pióra?', 0),
(11159, 'koKR', 'Brogg musi wiedzieć – $gprzyniosłeś:przyniosłaś; spokój gwałtownym duchom Kamiennych Maczug?', 0),
(11160, 'koKR', 'Ty przynieść sztandar Kamiennych Maczug?', 0),
(11161, 'koKR', 'Masz esencje? Brogg musi je mieć, żeby pomścić przyjaciół!', 0),
(11162, 'koKR', 'Brogg się zemści!', 0),
(11169, 'koKR', 'Udało ci się przetestować totem?', 0),
(11173, 'koKR', 'Masz ten jad? Morlann lada chwila odkryje, że go nie ma...', 0),
(11174, 'koKR', 'Udało ci się coś zdziałać przeciwko tym szlamom?', 0),
(11180, 'koKR', 'Czego $gdowiedziałeś:dowiedziałaś; się od duchów nawiedzających to miejsce?', 0),
(11181, 'koKR', 'Udało ci się zebrać trochę tego ziela? Musimy działać szybko, zanim zło, które stoi za tą plagą, umocni swoją władzę nad okolicą.', 0),
(11183, 'koKR', 'Już po wszystkim?', 0),
(11184, 'koKR', 'Wyglądasz na $gzadowolonego:zadowoloną; z siebie. $GPrzyszedłeś:Przyszłaś; odebrać nagrodę za tego potwornego raptora?', 0),
(11185, 'koKR', 'Co tam niesiesz, $N?', 0),
(11186, 'koKR', 'Co tam niesiesz, $N?', 0),
(11192, 'koKR', 'Udało ci się zdobyć trochę tego oleju z młocarzy?', 0),
(11193, 'koKR', 'Co dziś podać? Okoń morski jest całkiem niezły.', 0),
(11198, 'koKR', 'Składaj raport.', 0),
(11200, 'koKR', 'Co wykazały twoje poszukiwania w Wiosce Czarnego Kopyta?', 0),
(11201, 'koKR', 'Udało ci się znaleźć jakiś ślad rozkazów?', 0),
(11205, 'koKR', '$GZrobiłeś:Zrobiłaś; dobry użytek z tej pochodni?', 0),
(11207, 'koKR', '<Moxie odchodzi od zmysłów z niepokoju.>$B$BCzy ładunek przetrwał? $GZnalazłeś:Znalazłaś; coś?', 0),
(11209, 'koKR', 'Pamiętaj, umowa brzmi: „nie wracaj, dopóki coś cię nie ugryzie”.', 0),
(11217, 'koKR', '$GZnalazłeś:Znalazłaś; trochę żmijogonu?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(4500, 0, 'koKR', 'Nadrządca Mok\'Morokk szef. Ty robić, co ja mówić.', 0),
(4792, 0, 'koKR', 'Niektórzy myślą, że bagno jest do niczego... do niczego, mówią.', 0);
