INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(507, 'koKR', '--Dzień 13\nRuch wojsk w pobliżu Theramore się nasilił. Wielu ludzi opuściło miasto i w pośpiechu idzie na zachód.\n\n--Dzień 14\nKolejne oddziały opuszczają miasto. Szedłem za małą grupą i widziałem, jak zdejmują mundury, gdy tylko znaleźli się poza zasięgiem łuków z Theramore. Może to dezerterzy?\n\n--Dzień 15\nPodsłuchałem dziś, jak żołnierze z Theramore rozmawiali o strażnikach porzucających posterunki. Moje podejrzenia co do dezerterów muszą być słuszne\n', 0),
(527, 'koKR', '--Dzień 13 Ruch wojsk w pobliżu Theramore się nasilił. Wielu ludzi opuściło miasto i w pośpiechu idzie na zachód. --Dzień 14 Kolejne oddziały opuszczają miasto. Szedłem za małą grupą i widziałem, jak zdejmują mundury, gdy tylko znaleźli się poza zasięgiem łuków z Theramore. Może to dezerterzy? --Dzień 15 Podsłuchałem dziś, jak żołnierze z Theramore rozmawiali o strażnikach porzucających posterunki. Moje podejrzenia co do dezerterów muszą być słuszne ', 0),
(548, 'koKR', '--Dzień 16\nUleg i Thargil wrócili z misji w dokach Theramore. Widzieli w porcie nowy statek: „Krwawiącego Wróbla”. Statek przypłynął z Przystani Menethilów w Azeroth.\n\nJutro Uleg i Thargil wrócą do doków i zakradną się na pokład. Mają nadzieję znaleźć dokumenty polityczne, które ujawnią stosunki między Theramore a Przymierzem.', 0),
(579, 'koKR', '--Dzień 17\nUleg wrócił z misji. Zawiódł, a Thargil został pojmany. Wysłałem Ulega, by dostarczył ten raport Nazeerowi.\n\nJa zostanę tutaj. Zauważyłem wzmożony ruch statków u wybrzeży Theramore. Będę dalej obserwował i osobiście zamelduję o wszystkim, co warte uwagi.', 0),
(911, 'koKR', 'Zdobądź nefryt. Kryje się w wielu różnych miejscach. Jest rzadki, ale jeśli porozmawiasz z kowalem albo inżynierem, może będą mieli jeden czy dwa na zbyciu.', 0),
(991, 'koKR', 'Zdobądź jeżynę naładowaną piorunem. Aby ją zdobyć, zbierz 10 totemicznych patyków Suchokorych od trolli Suchokorych z Wyżyn Aratorskich. Zanieś patyki do Kręgu Zewnętrznego Spętania, kamiennego kręgu na tych samych wyżynach. Połóż patyki na środkowym kamieniu kręgu i zaczekaj, aż uderzy w niego piorun. Gdy to się stanie, powstanie jeżyna naładowana piorunem.', 0),
(2829, 'koKR', 'Drogi pamiętniku,$B$Bdziś mój arcywróg, Narain Wróżbiarz, próbował mnie oszukać, wysyłając swoich kumpli, żeby zajęli jego miejsce na egzekucji. JEGO egzekucji. Wyobrażasz sobie?$B$BZadałem sobie tyle trudu, żeby obmyślić ten diaboliczny plan wywabienia go z tej przeklętej chaty, a on wyskakuje z czymś takim? Nieważne... Jestem zbyt wściekły, żeby dalej pisać. Wrócę później.', 0),
(2830, 'koKR', 'Drogi pamiętniku,$B$Bpo ostatnim wpisie wybiegłem z kryjówki w szale. Ależ byłem wściekły. Postanowiłem przeprojektować mundury moich sług, żeby lepiej oddawały mój wewnętrzny niepokój. Trochę mi ulżyło, ale czegoś brakuje. Zaraz wracam...', 0),
(2831, 'koKR', 'Drogi pamiętniku,$B$Bjuż mi lepiej. Sprałem jednego z moich sług, aż się rozbeczał jak mała dziewczynka.$B$BHmm... Teraz jest mi trochę głupio. Chwileczkę! Do licha, przecież jestem ZŁYM geniuszem! Złym, rozumiesz? Jestem sobą strasznie rozczarowany. Zaraz wracam.', 0),
(2832, 'koKR', 'Drogi pamiętniku,$B$Buściskałem go i powiedziałem, żeby tak trzymał. Teraz czuję się lepiej. Niech to zostanie między nami, pamiętniku.$B$BNa czym to ja skończyłem? A tak, NARAIN! ARGH!!! Nienawidzę tego typa. To przecież Narain psuł średnią na każdym egzaminie, kiedy studiowaliśmy w Instytucie Majsterkowania w Gnomoregan.$B$BWylać mnie ze szkoły, co? Jak dla mnie, Gnomoregan dostało to, na co zasłużyło!$B$BTo wszystko na dziś. Śpij dobrze, pamiętniku!', 0),
(2833, 'koKR', 'Drogi pamiętniku,$B$Bchyba się starzeję. Zupełnie zapomniałem, że opowiadałem ci o Narainie i jego podstępie. W każdym razie, kiedy zamiast Naraina zobaczyłem przebranego za niego podstawionego gościa, tak się wściekłem, że kazałem Numerowi Dwa zniszczyć tego głupca!$B$BWsiadłem do mojej latającej maszyny i zacząłem wydzierać kartki z tej jego cennej, głupiej, durnej książki o smoczym języku. Co za pozer! Kto w ogóle czyta po smoczemu? Tak go nienawidzę!', 0),
(2834, 'koKR', 'Drogi pamiętniku,$B$Bprzepraszam, zasnąłem. Więc leciałem wściekły i wyrzucałem rozdziały tej głupiej książki. Pode mną, w Wąwozie Mrocznego Szeptu, zobaczyłem demona i postanowiłem zrobić z pierwszego rozdziału magiczne tornado z papieru, które posiekało go na milion kawałków! To było wyzwalające. Magia + papier = frajda.$B$BZrobiło mi się od tego całkiem wesoło, więc postanowiłem polecieć do Wschodnich Królestw. Pierwszy przystanek: Ognista Czeluść. Narain zawsze gadał o tym miejscu! „Ognista Czeluść to, Ragnaros tamto...”', 0),
(2835, 'koKR', 'No i wiesz co? Skoro tak je lubi, to może spodoba mu się składanie książki z powrotem do kupy, kiedy będzie musiał iść do Ognistej Czeluści i wskrzeszać rozdział ze sterty popiołu! Ha!$B$BSkoro już byłem w okolicy, uznałem, że któryś z tych ośliniających się techników w laboratorium starego Victora Nefariusa znajdzie zastosowanie dla tych smoczych bzdetów. Bomba w dół!', 0),
(2836, 'koKR', 'To zaczynało się robić czymś w rodzaju sportu. Naprawdę wciągnęło mnie rozrywanie tej przeklętej książki!$B$BKolejne zrzuty poszły łatwo.$B$BPodmiasto, siedziba cuchnących, gnijących umarlaków i chyba najlepszego chili, jakie w życiu jadłem, dostało jeden rozdział. Wichrogród, stolica sera, drugi. Pamiętniku, czy kładłeś kiedyś ser z Wichrogrodu na chili z Podmiasta? HALO? Tu powinny się rozdzwonić wszystkie dzwonki alarmowe.', 0),
(2837, 'koKR', 'W tym momencie zaczynałem być zmęczony, więc zawróciłem latającą maszynę i skierowałem się do domu, ale nie bez dwóch kolejnych przystanków. Przeleciałem nisko nad lordem Kazzakiem i jego demonami w Skażonej Bliźnie (nie znosi, kiedy to robię) i wetknąłem kolejny rozdział do komina Onyxii.$B$BZmęczony. Idę spać.', 0),
(3032, 'koKR', 'Garnie,$B$Bnie muszę ci przypominać, jak ważna jest twoja misja – chroń swój cenny ładunek za wszelką cenę. Zgodnie z obietnicą sukces i dyskrecja zostaną sowicie wynagrodzone.$B$BOgranicz do minimum paplaninę swoich „wspólników”, słuchaj załogi, a wszystko będzie dobrze. Czekam na wieść o twoim powodzeniu.', 0),
(3033, 'koKR', 'Wysłałem ci znaczne siły, starszy, lecz musisz działać rozważnie. Twoim pierwszym zadaniem będzie powstrzymać pochód kundli Przymierza w głąb naszych ziem. Co śmielsi ludzie zaczęli już wznosić duży budynek na granicy z Pustkowiami.\n\nDopilnuj, by wiedzieli, że ich pobratymcy nie są mile widziani poza granicami ich nędznego Theramore. Na koniec słowo przestrogi dla ciebie, starszy: nie zdradzaj swoich planów ogrom z Paprotni. Te bydlaki nie są zdolne do choćby odrobiny dyskrecji.\n\n- Agashem', 0),
(3034, 'koKR', 'Jednym z najstraszliwszych stworzeń, jakie kiedykolwiek widziały moje oczy, jest Tethyr. Moje oczy ujrzały tę bestię tylko raz i uważam za niewiarygodne szczęście, że udało mi się przeżyć!$B$BByła ciemna i burzliwa noc. Przez kłębiące się morze i zacinający deszcz ledwo było widać światło latarni morskiej Theramore. Robiliśmy, co w naszej mocy, żeby sterować w jego stronę. Nagle przed naszym statkiem spomiędzy fal wystrzeliła bestia!', 0),
(3035, 'koKR', 'Potężne stworzenie rozwarło szeroko paszczę, miotając w nasz okręt pociski lodowatej wody. Straszliwe szczęki zacisnęły się na dziobie statku i oderwały go od kadłuba. Marynarze i ładunek z impetem wypadli do morza, a resztki statku zniknęły pod falami.$B$BOstatnie, co pamiętam, to lot z roztrzaskanego kadłuba, uderzenie o atramentowo czarną wodę i zanurzenie pod fale. Świat pociemniał i wydawało mi się, że to już mój ostatni oddech. Po przebudzeniu w lecznicy Theramore stało się dla mnie jasne, że ktoś musi opowiedzieć naszą historię.$B', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15552, 0, 0, 'koKR', 'Nie przywitasz się ze starym przyjacielem, Narainie? Kogo się spodziewałeś?'),
(15552, 2, 0, 'koKR', 'A więc... Myślałeś, że zdołasz mnie oszukać, co? Mnie, największego zbrodniczego geniusza w dziejach Azeroth?');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(1511, 'koKR', '%s zaczyna rzucać zaklęcie na serca i języki.', '', 0),
(1512, 'koKR', 'Miot Onyxii!', '', 0),
(1514, 'koKR', 'Ja dalej szef ogrów. Ha!', '', 0),
(1515, 'koKR', 'Maluch chcieć walczyć z nadrządcą Mok\'Morokkiem? Ja cię pobić! Ja tu szef!', '', 0),
(1523, 'koKR', 'Ja się bać! Ja teraz uciekać!', '', 0),
(1632, 'koKR', 'Przyniesie ci miodu, przyniesie ci piwa...', '', 0),
(1633, 'koKR', 'Z uśmiechem od ucha do ucha przybywa...', '', 0),
(1634, 'koKR', 'Rok w rok nam wszystkim wiernie służy...', '', 0),
(1635, 'koKR', 'Zwiemy go Uśmiechniętym Jimem...', '', 0),
(1669, 'koKR', 'Widziałem ogień na tamtej wyspie. I człowieka. Chodźmy to sprawdzić, $n.', '', 0),
(1670, 'koKR', 'To Reethe, bez dwóch zdań. Chodźmy posłuchać, co ma do powiedzenia, co?', '', 0),
(1671, 'koKR', '%s kładzie zwój na stole i czyta...', '', 0),
(1672, 'koKR', 'Na Światłość! Ten przeklęty szpieg był dobry! Cieszę się, że nie żyje.', '', 0),
(1673, 'koKR', 'Dziękuję za ten raport, $n. Teraz jest jasne, że musimy zaostrzyć patrole w okolicach Theramore.', '', 0),
(1674, 'koKR', 'C-czego chcesz? Zostaw mnie w spokoju...', '', 0),
(1675, 'koKR', 'Przysięgam, niczego ci nie ukradłem! Masz, weź trochę moich zapasów, tylko idź sobie!', '', 0),
(1707, 'koKR', 'Po prostu powiedz nam, co wiesz o karczmie „Cienisty Wypoczynek”, a nie rozwalę ci czaszki.', '', 0),
(1708, 'koKR', 'Ja... No, może i wyniosłem to czy owo z karczmy... ale co to może obchodzić ogra?', '', 0),
(1709, 'koKR', 'Słuchaj no, jeśli nie powiesz mi o pożarze, to...', '', 0),
(1710, 'koKR', 'Ani kroku dalej, ogrze!', '', 0),
(1711, 'koKR', 'I nic nie wiem o tym twoim pożarze...', '', 0),
(1722, 'koKR', 'Ugh... Hallan, nie sądziłem, że cię na to stać...', '', 0),
(1724, 'koKR', 'Niech to szlag! Ani mi się waż umierać, człowieku!', '', 0),
(1725, 'koKR', 'Masz dziś szczęśliwy dzień. Dobra, powiem. Tylko zostaw mnie w spokoju. Słuchaj, nie uwierzysz mi, ale to by... och, Światłości, ta dziewczyna jednak umie strzelać...', '', 0),
(1726, 'koKR', 'Jesteś jeszcze z nami, Reethe?', '', 0),
(1729, 'koKR', 'Jak dla mnie nie żyje. W tym stanie na nic nam się nie przyda. Lepiej wróć i powiedz Krogowi, co się stało.', '', 0),
(1730, 'koKR', 'A tak przy okazji, dzięki za osłanianie tyłów.', '', 0),
(1731, 'koKR', 'Co to było? Nic nie słyszysz?', '', 0),
(1732, 'koKR', '%s zatacza się do tyłu, gdy strzała wbija mu się głęboko w pierś.', '', 0),
(1753, 'koKR', 'Tesoran! Potrzebuję kogoś – najlepiej Falgrana Hastila – kto zbada trop, na który $n $gnatrafił:natrafiła; przy śladach koło karczmy „Cienisty Wypoczynek”.', '', 0),
(1754, 'koKR', 'Już się robi, kapitanie.', '', 0),
(1756, 'koKR', 'Dobra! Dobra! Poddajemy się... Tylko opuśćcie broń, będę współpracował!', '', 0),
(1789, 'koKR', 'Niezły strzał... ale nie idealny. Może trochę bardziej w lewo.', 'Niezły strzał... ale nie idealny. Może trochę bardziej w lewo.', 0),
(1790, 'koKR', 'Tym razem ledwo trafiłem w tarczę. Hmm... może trzeba poprawić z powrotem w prawo.', 'Tym razem ledwo trafiłem w tarczę. Hmm... może trzeba poprawić z powrotem w prawo.', 0),
(1791, 'koKR', 'Łooo! Patrz, w sam środek!', 'Łooo! Patrz, w sam środek!', 0),
(1792, 'koKR', 'Ups! Trochę obok. Nawet nie trafiłem w tarczę!', 'Ups! Trochę obok. Nawet nie trafiłem w tarczę!', 0),
(3161, 'koKR', 'Przyniesie ci miodu$bPrzyniesie ci piwa$bZ uśmiechem od ucha do ucha przybywa$bRok w rok nam wszystkim wiernie służy$bZwiemy go Uśmiechniętym Jimem.', '', 0),
(4225, 'koKR', 'Straż Theramore to najlepsi żołnierze Przymierza stacjonujący w Kalimdorze. Naszym obowiązkiem jest stać na straży praw Przymierza, nawet tak daleko od naszych domów.', '', 0),
(4226, 'koKR', 'Niewiele wiemy o spaleniu karczmy „Cienisty Wypoczynek”, poza tym, że żona i dziecko Jamesa Hyala nie zdołali uciec.$b$bUdało nam się wyciągnąć Jamesa, ale od tamtej pory nie jest już sobą.$b$bMamy wiele tropów, ale mało dowodów. Liczymy, że dzięki staraniom straży i czujnej pomocy mieszkańców Theramore rozwikłamy tę straszliwą zbrodnię.$b$bJeśli chcesz pomóc w śledztwie, to, co zostało z karczmy, znajdziesz na granicy z Pustkowiami.', '', 0),
(4227, 'koKR', 'Co wiesz o karczmie „Cienisty Wypoczynek”?', 'Co wiesz o karczmie „Cienisty Wypoczynek”?', 0),
(7324, 'koKR', 'W nogi!', 'W nogi!', 0),
(7325, 'koKR', 'To Proudmoore! Zmykajmy stąd!', 'To Proudmoore! Zmykajmy stąd!', 0),
(7340, 'koKR', 'Uciekajmy stąd!', 'Uciekajmy stąd!', 0),
(7341, 'koKR', 'Nie dajcie się złapać!', 'Nie dajcie się złapać!', 0),
(7342, 'koKR', 'Jak nas złapie, pościnają nam głowy!', 'Jak nas złapie, pościnają nam głowy!', 0),
(7638, 'koKR', 'Theramore słynie z wyjątkowego szkolenia wojowników, ale obawiam się, że nie mogę ci pomóc.', 'Theramore słynie z wyjątkowego szkolenia wojowników, ale obawiam się, że nie mogę ci pomóc.', 0),
(7639, 'koKR', '$GPrzyszedłeś:Przyszłaś; szkolić się ze strażą Theramore, co?', '$GPrzyszedłeś:Przyszłaś; szkolić się ze strażą Theramore, co?', 0),
(7640, 'koKR', 'Tak. Właśnie po to.', 'Tak. Właśnie po to.', 0),
(7713, 'koKR', 'Przestań się tak na mnie gapić. Może nie jestem poszukiwaczem przygód jak ty, ale to nie znaczy, że nie mogę mieć trochę mięśni. Od tego ciągłego mieszania ręce robią się silne.', '', 0),
(8195, 'koKR', 'Ubierałem królów. Z odpowiednim szkoleniem ty też możesz.', '', 0),
(8204, 'koKR', '', 'Bardzo lubię tu siedzieć i wsłuchiwać się w szum Wielkiego Morza. Och, co? Tak, jest statek, który zabierze cię do Przystani Menethilów. Zawija tu od czasu do czasu.', 0),
(11107, 'koKR', '%s przygląda ci się podejrzliwie.', '', 0),
(11109, 'koKR', 'Przejrzałem twoje przebranie! Numer Dwa! Numer Dwa zabić!', '', 0),
(13498, 'koKR', '', 'Czy to Balandar Jasnogwiazda przysłał cię, żeby mnie uratować?', 0),
(13499, 'koKR', 'Balandar przysłał mnie, żeby cię stąd wydostać i odzyskać jego ładunek. Czeka na ciebie w Paprotni.', 'Balandar przysłał mnie, żeby cię stąd wydostać i odzyskać jego ładunek. Czeka na ciebie w Paprotni.', 0),
(13500, 'koKR', '', 'Chyba dotrę do Paprotni sama. Ładunek trzymają na szczycie wieży. Uważaj na siebie!', 0),
(18907, 'koKR', 'Już się robi, kapitanie.', 'Już się robi, kapitanie.', 0),
(22038, 'koKR', 'Tajemnicze ślady kopyt, osmalone tarcze, zagubione odznaki... jak to wszystko poskładać w całość?', '', 0),
(22039, 'koKR', 'Ta zbrodnia nie może pozostać niewyjaśniona. Położenie karczmy i gwałtowność, z jaką ją zniszczono, czynią z tego bardzo delikatną sprawę. Oglądaj to miejsce z najwyższym szacunkiem, $gprzyjacielu:przyjaciółko;.', '', 0),
(22041, 'koKR', 'Możesz jeszcze raz rozsypać proszek odblaskowy?', 'Możesz jeszcze raz rozsypać proszek odblaskowy?', 0),
(22042, 'koKR', 'Hmm... Ciekawe...', '', 0),
(22043, 'koKR', 'Głupi magowie... zawsze zużyją resztkę odczynnika i nigdy go nie uzupełnią.', '', 0),
(22044, 'koKR', 'Znowu narzeka na odczynniki? A pamięta chociaż, w jakim stanie zostawił ostatnio księgi przywołań?', '', 0),
(22045, 'koKR', 'No, gdzie to jest?', '', 0),
(22046, 'koKR', 'Jeśli myślisz, że zdołasz nas powstrzymać, to się mylisz, „przyjacielu”.', '', 0),
(22047, 'koKR', 'Nie przeszkodzisz nam w ujawnieniu prawdy o tchórzostwie Jainy!', '', 0),
(22048, 'koKR', 'Ci ludzie poznają admirała Proudmoore\'a jako prawdziwego bohatera, którym był!', '', 0),
(22049, 'koKR', 'To przez takich jak ty Przymierze słabnie, a Horda dostaje zaproszenie, by odebrać nam wszystko, o co walczyliśmy!', '', 0),
(22050, 'koKR', 'Miło widzieć, że z dumą bronisz Theramore, przyjacielu.', '', 0),
(22051, 'koKR', 'Kiedy skończysz służbę, chodźmy do karczmy. Postawię kolejkę i powspominamy stare dobre czasy.', '', 0),
(22052, 'koKR', 'Nie chciałbyś, żeby tamte czasy wróciły? Mam przyjaciół, którzy wiedzą, jak to zrobić...', '', 0),
(22053, 'koKR', 'Wyglądasz na kogoś rozsądnego, przyjacielu. Pamiętasz chwalebne dni Theramore, zanim Jaina kazała nam porzucić walkę z Hordą? Nie masz dość tego, że każą ci trzymać miecz w pochwie, podczas gdy orkowie wciąż nas prowokują?', '', 0),
(22054, 'koKR', 'Twoja propaganda na mnie nie działa. Rozsiewaj swoje zdradzieckie plugastwo gdzie indziej, zdrajco!', 'Twoja propaganda na mnie nie działa. Rozsiewaj swoje zdradzieckie plugastwo gdzie indziej, zdrajco!', 0),
(22105, 'koKR', '', 'Szkoda by było, żeby te ulotki się zmarnowały, prawda?', 0),
(22107, 'koKR', '', 'Wystarczy odrobina twórczej redakcji i od razu są dużo przydatniejsze...', 0),
(22111, 'koKR', 'O, dzięki.', 'O, dzięki.', 0),
(22112, 'koKR', '%s czyta ulotkę.', '%s czyta ulotkę.', 0),
(22113, 'koKR', 'To... to jakiś żart, prawda?', 'To... to jakiś żart, prawda?', 0),
(22114, 'koKR', 'Dawno nie czytałem nic równie zabawnego. Od razu mam lepszy dzień!', 'Dawno nie czytałem nic równie zabawnego. Od razu mam lepszy dzień!', 0),
(22115, 'koKR', 'Banda wariatów! Ty naprawdę w to wierzysz?', 'Banda wariatów! Ty naprawdę w to wierzysz?', 0),
(22116, 'koKR', 'Nigdy bym się do czegoś takiego nie przyłączył. Ale to sobie zatrzymam. Przyda się w wychodku...', 'Nigdy bym się do czegoś takiego nie przyłączył. Ale to sobie zatrzymam. Przyda się w wychodku...', 0),
(22160, 'koKR', 'Hmm... stare monety... brzydka biżuteria...', '', 0),
(22161, 'koKR', 'Znowu brzydka biżuteria... listy do domu... zaczynam tracić nadzieję!', '', 0),
(22162, 'koKR', 'Hej... a co to? Para kajdan, i to nie byle jakich. Zaczarowanych. Ten ładunek to nie była rzecz... to był człowiek!', '', 0),
(22164, 'koKR', '', 'Witaj, $N. Uczę się sztuki obchodzenia się z gryfami od Baldruca, o tam. Mam nadzieję, że pewnego dnia będę prowadzić własną stajnię gryfów.', 0),
(22176, 'koKR', 'Lady Jaina kazała mi porozmawiać z tobą o gryfie, żeby z powietrza przepatrzeć Wyspę Alcaz.', 'Lady Jaina kazała mi porozmawiać z tobą o gryfie, żeby z powietrza przepatrzeć Wyspę Alcaz.', 0),
(22198, 'koKR', 'Miej się na baczności. Jesteśmy pierwszą linią obrony Theramore przed jego licznymi wrogami na bagnach.', '', 0),
(22203, 'koKR', 'Odkąd dezerterzy zajęli Stracony Cypel, Wieża Północnego Cypla jest najdalej wysuniętą placówką Theramore.', '', 0),
(22244, 'koKR', '', 'James? James... Nie, nie jesteś Jamesem, ale wiem, kim jesteś...', 0),
(22245, 'koKR', '', 'To ty $gwytropiłeś:wytropiłaś; bydlaków, którzy nam to zrobili.', 0),
(22246, 'koKR', '', 'Tak bardzo się starałam powiedzieć Jimowi... komukolwiek... kto za tym stoi, ale nie umiałam znaleźć sposobu...', 0),
(22247, 'koKR', '', 'Dziękuję za pomoc, nam i Jimowi. Jeśli go zobaczysz, powiedz mu, że mały Jimmy i ja kochamy go i że na niego czekamy.', 0),
(22249, 'koKR', '', 'Nie wiem, kiedy znów zobaczymy tatusia, Jimmy, ale wiem, że cię kocha i bardzo za tobą tęskni.', 0),
(22257, 'koKR', 'Witaj na Posterunku Strażniczym, $N.', '', 0),
(22285, 'koKR', 'Żałosny śmiertelniku, Onyxia nikomu nie podlega!', '', 0),
(22286, 'koKR', 'Twoje żałosne wyzwanie nie uszło uwagi. Z przyjemnością się tobą pobawię, zanim zginiesz.', '', 0),
(22290, 'koKR', 'Brogg cieszy się, że gobliny z Zębłotki pozwoliły mu tu zostać, ale czasem Broggowi się zdaje, że słyszy, jak się z niego śmieją.', '', 0),
(22319, 'koKR', 'Jeśli chcesz porozmawiać z uczniem Garionem, znajdziesz go w chacie razem z Tabethą. Przynajmniej tam nie podkradnie wszystkich odczynników.', '', 0),
(22320, 'koKR', 'Szkoda, że nie mamy tu kapłana ani druida. Nie mogę wrócić do nauki, dopóki nie wyliżę się z ran.', '', 0),
(22348, 'koKR', 'Przyniosłem ci prezent na nowe mieszkanie, Jarlu.', '', 0),
(22349, 'koKR', 'No dalej, otwórz. Myślę, że ci się spodoba.', '', 0),
(22350, 'koKR', 'Jarlu?', '', 0),
(22351, 'koKR', 'Jak nie da się tego zjeść, to tego nie chcę.', '', 0),
(22352, 'koKR', 'Jarlu, odkąd przyjechałem, nie jesteś sobą. Co się dzieje?', '', 0),
(22353, 'koKR', 'Nic. Chcesz mi pomóc upichcić gulasz z żabich udek?', '', 0),
(22354, 'koKR', 'Przyjechałem tu, żeby cię odwiedzić, Jarlu! A zastaję cię w pustej chacie na końcu świata, jak bełkoczesz o żabach? Jesteś beznadziejny!', '', 0),
(22359, 'koKR', 'Odejdź, ktokolwiek jesteś! Wzgórze Czarownic jest moje... moje!', 'Odejdź, ktokolwiek jesteś! Wzgórze Czarownic jest moje... moje!', 0),
(22360, 'koKR', 'To było... straszne... demon...', 'To było... straszne... demon...', 0),
(22361, 'koKR', 'Dwór... ktoś jeszcze... wkrótce zostanie pochłonięty...', 'Dwór... ktoś jeszcze... wkrótce zostanie pochłonięty...', 0),
(22362, 'koKR', 'Ciemność... zepsucie... nadeszły zbyt szybko, by ktokolwiek się zorientował...', 'Ciemność... zepsucie... nadeszły zbyt szybko, by ktokolwiek się zorientował...', 0),
(22363, 'koKR', 'Czego tu szukasz, obcy przybyszu? Znajdziesz tylko ból! Nasz los stanie się twoim...', 'Czego tu szukasz, obcy przybyszu? Znajdziesz tylko ból! Nasz los stanie się twoim...', 0),
(22364, 'koKR', 'Ciemność pochłonie wszystko... wszystkich żywych...', 'Ciemność pochłonie wszystko... wszystkich żywych...', 0),
(22365, 'koKR', 'Dla nas jest już za późno, żywa istoto. Uchodźcie stąd, ty i twój przyjaciel, zanim i was... zagarnie...', 'Dla nas jest już za późno, żywa istoto. Uchodźcie stąd, ty i twój przyjaciel, zanim i was... zagarnie...', 0),
(22366, 'koKR', 'Dla Jarla jest już za późno... to coś trzyma go zbyt mocno...', 'Dla Jarla jest już za późno... to coś trzyma go zbyt mocno...', 0),
(22370, 'koKR', 'Ta ziemia należała do mnie na długo, zanim twój nędzny ród postawił tu stopę.', '', 0),
(22371, 'koKR', 'Wszyscy, którzy się tu zapuszczają, należą do mnie, ty także!', '', 0),
(22378, 'koKR', 'Na tej tablicy przedstawiciele Parochlebców w Zębłotce wywieszają ogłoszenia o nagrodach i ofertach pracy.', '', 0),
(22379, 'koKR', '', 'Nie sądzę, żeby Drazzitowi udało się znaleźć kogoś, kto zabije tego raptora. No bo już dwa razy podnosił nagrodę...', 0),
(22392, 'koKR', 'Lepiej się odsuń. Patroszenie ryb to brudna robota.', '', 0),
(22416, 'koKR', 'Ja zgnieść marny przyjaciel smoków!', '', 0),
(22417, 'koKR', 'Ty opuścić ziemie Kamiennych Maczug, już!', '', 0),
(22418, 'koKR', 'Czemu ty budzić ducha? Gdzie inne Kamienne Maczugi?!', '', 0),
(22419, 'koKR', '%s wygląda na dość osłabionego, by go schwytać!', '', 0),
(22436, 'koKR', '', 'Sytuacja jest tu gorsza, niż myślałam! Ze sterowca została niewiele więcej niż kupa powykręcanego metalu i płonącego paliwa!', 0),
(22438, 'koKR', 'Dziękuję! Kto wie, co te bydlaki by ze mną zrobiły.', 'Dziękuję! Kto wie, co te bydlaki by ze mną zrobiły.', 0),
(22440, 'koKR', '', 'Witaj w Theramore, $N.', 0),
(22447, 'koKR', 'Strzelcy, zbiórka! Zająć pozycje!', '', 0),
(22448, 'koKR', 'Przygotować się do strzału na mój rozkaz! Gotowi, cel...', '', 0),
(22449, 'koKR', 'OGNIA DO WOLI!', '', 0),
(22469, 'koKR', 'Poddaję się! Opuść broń!', '', 0),
(22470, 'koKR', 'Pójdę z tobą. Tylko oszczędź moich ludzi. To dobre chłopaki, po prostu popełnili błąd...', '', 0),
(22478, 'koKR', 'Nie mam czasu na rozmowy, chyba że to coś pilnego, $gobywatelu:obywatelko;. Wrota Theramore to mój najważniejszy obowiązek.', '', 0),
(22479, 'koKR', 'Porucznik Aden zawsze zgłasza się na ochotnika do pilnowania wrót. Mnie to pasuje.$B$BMam posterunek, z którego świetnie widzę jednocześnie swoich strażników I córki rzemieślników.', '', 0),
(22480, 'koKR', 'Czy to zmiana warty? Na pewno już prawie pora. Zresztą, jeśli i tak chcesz mnie zmienić, daj znać. Przydałby mi się kieliszek. Albo trzy.', '', 0),
(22481, 'koKR', 'Dzięki Światłości, że Nieskorni nie mają zielonego pojęcia o nurkowaniu!', '', 0),
(22482, 'koKR', 'Nie mam już naprawionego sprzętu do nurkowania. Masz może zapasowy?', 'Nie mam już naprawionego sprzętu do nurkowania. Masz może zapasowy?', 0),
(22511, 'koKR', 'Witaj w Theramore.', '', 0),
(22549, 'koKR', 'Wyglądasz na inteligentną osobę. Może przeczytasz jedną z tych ulotek i trochę się nad nią zastanowisz?', 'Wyglądasz na inteligentną osobę. Może przeczytasz jedną z tych ulotek i trochę się nad nią zastanowisz?', 0),
(22555, 'koKR', '...50 procent zniżki na bieliznę dezertera? Co to za bzdury?', '...50 procent zniżki na bieliznę dezertera? Co to za bzdury?', 0),
(22556, 'koKR', '...jako dezerter będziesz się oddawać takim zajęciom jak pływanie na uwięzi i strzyżenie psów? Co za absurd!', '...jako dezerter będziesz się oddawać takim zajęciom jak pływanie na uwięzi i strzyżenie psów? Co za absurd!', 0),
(22559, 'koKR', '...dezerterzy dążą do Theramore, w którym obywatele będą mogli żonglować o każdej porze dnia? Co to za brednie?', '...dezerterzy dążą do Theramore, w którym obywatele będą mogli żonglować o każdej porze dnia? Co to za brednie?', 0),
(22561, 'koKR', '...ustanowić kurczaka oficjalnym symbolem Theramore?! Ci goście są stuknięci!', '...ustanowić kurczaka oficjalnym symbolem Theramore?! Ci goście są stuknięci!', 0),
(22562, 'koKR', '...utworzyć fundusz na zakup żelu do włosów? Lubię swoje włosy takie, jakie są, dzięki!', '...założyć fundusz na zakup żelu do włosów? Lubię swoje włosy takie, jakie są, dzięki!', 0),
(22588, 'koKR', 'Zdaje się, że już o tym rozmawialiśmy, Broggu. Nie możesz zostać w tym budynku. Jasne, ty się w nim zmieścisz, ale dla nikogo innego nie ma już miejsca!', '', 0),
(22589, 'koKR', 'Ty mówić, że Brogg może tu zostać! Ty obiecać Broggowi pomóc odzyskać kopiec klanu Kamiennych Maczug!', '', 0),
(22590, 'koKR', 'Tak, mówiliśmy, że możesz tu zostać, ale ten budynek to nasza kwatera główna! Trzymamy tu wszystkie podręczniki i plany!', '', 0),
(22591, 'koKR', 'Ale tylko ten budynek pasować na Brogga! Gobliny robić za małe budynki!', '', 0),
(22592, 'koKR', 'Ja bym raczej powiedział, że to ogry wyszły za duże! Widzę, że teraz nie przekonam cię do przeprowadzki, ale nie myśl sobie, że to na stałe!', '', 0),
(22596, 'koKR', 'Nigdy nie nazwę Paprotni swoim domem. To by znaczyło porzucić nadzieję na odzyskanie ziem, które prawnie nam się należą.', '', 0),
(22633, 'koKR', 'Udało się! Pokonaliśmy Tethyra!', '', 0),
(22634, 'koKR', 'Pokonaliśmy morskiego potwora!', '', 0),
(22943, 'koKR', 'Głód? Spać tu też można.', '', 0),
(24293, 'koKR', 'Wejdź, schroń się przed popiołem i błotem. Osusz się chwilę.', '', 0),
(26998, 'koKR', 'Hm? Och. Wybacz, jeśli wydaję się nieobecny; niepokoję się o ludzi z Północnej Strażnicy. Powinienem był wysłać im na pomoc kilku moich uczniów. No więc, w czym mogę pomóc?', 'Hm? Och. Wybacz, jeśli wydaję się nieobecny; niepokoję się o ludzi z Północnej Strażnicy. Powinienem był wysłać im na pomoc kilku moich uczniów. No więc, w czym mogę pomóc?', 0),
(26999, 'koKR', 'Hm? Och. Wybacz, jeśli wydaję się nieobecny; niepokoję się o ludzi z Północnej Strażnicy. Powinienem był wysłać im na pomoc kilku moich uczniów...', 'Hm? Och. Wybacz, jeśli wydaję się nieobecny; niepokoję się o ludzi z Północnej Strażnicy. Powinienem był wysłać im na pomoc kilku moich uczniów...', 0),
(27005, 'koKR', '', 'Moje nauki przydadzą się tylko magom. Nie mogę ci pomóc, $N.', 0),
(27006, 'koKR', '', 'Sinu a\'manore. Jeśli chcesz się nauczyć otwierać portal do Theramore, mogę ci pokazać.', 0),
(51958, 'koKR', 'Wszystkie machiny oblężnicze są prawie gotowe, więc zaczynam się trochę nudzić!\nNie jesteś przypadkiem inżynierem? Może porównamy plany...?', '', 0);
